// Cyrus MOD HEALTH TELEMETRY (R4): the signal schema. Pure + client-safe.
//
// What it is: opt-in, aggregate-only health signals about Cyrus mods running on servers whose owner switched it on:
//   boot_ok            the server finished starting with the mod enabled
//   enable_error       the mod threw while being enabled (Paper "Error occurred while enabling")
//   exception          the mod threw at runtime (event handler / scheduled task), reduced to a SIGNATURE
//   crash              the server crashed or crash-looped and the crash names the mod
//   command_registered / command_missing   a command the mod declares is / is not registered after start
// What it never holds: player names, UUIDs, IP addresses, chat, world or server names, coordinates, file paths,
// exception MESSAGES or any free text. Only fixed enums, version ids, hashes and counts pass the validator; an
// unknown field or a string outside its pattern rejects the whole signal (fail closed).
//
// Identity: `serverKey` is an HMAC of the server id with a salt that ROTATES every retention window (30 days), so a
// server's signals can be counted as "distinct servers" inside one window but cannot be linked across windows.
// Retention: raw daily signals 30 days, aggregates 180 days (./retention.ts).

export const TELEMETRY_SCHEMA = 1 as const;
export const TELEMETRY_FLAG = "CYRUS_HEALTH_TELEMETRY";
export const CONSENT_SCOPE = "cyrus-mod-health-v1" as const;
export const SIGNAL_EVENTS = ["boot_ok", "enable_error", "exception", "crash", "command_registered", "command_missing"] as const;
export type SignalEvent = (typeof SIGNAL_EVENTS)[number];

export type HealthSignal = {
  v: 1;
  /** UTC day bucket, YYYY-MM-DD. No finer time is ever stored. */
  day: string;
  /** HMAC-SHA256(serverId, window salt), 32 hex. Rotates with the window. */
  serverKey: string;
  /** Rotating window number the serverKey belongs to (floor(epochDay / 30)). */
  window: number;
  /** The Cyrus build the server runs (ModBuild id) - a Cyrus id, not player data. */
  buildId: string;
  /** Minecraft version id of the server (registry form, e.g. 1.21.11). */
  mcVersion: string;
  software: "paper" | "purpur" | "folia" | "spigot" | "other";
  event: SignalEvent;
  /** exception / crash / enable_error only: sig_<16 hex> of (exception class + first frame in the mod's packages). */
  signature?: string;
  /** exception / crash / enable_error only: the exception CLASS (e.g. java.lang.NoSuchMethodError), never its message. */
  exceptionClass?: string;
