#   scripts/cyrus/cost-export.sh [--since 2026-10-01] [--daily] [--json]     DB: CYRUS_DATABASE_URL, else DATABASE_URL
# Rows: build id, created/finished, status, error code, MC version, tier/model (ModBuild.cyrus.model), attempts,
# duration, costUsd (as reported by the build service, API-equivalent USD), user as a salted hash (no raw ids/emails
# leave the database; salt = CYRUS_EXPORT_SALT). --daily: per-day builds, succeeded, failed, total/avg/p95 cost.
set -euo pipefail
SINCE=$(date -u -d '30 days ago' +%F); DAILY=0; JSON=0
while [ $# -gt 0 ]; do case "$1" in --since) SINCE="$2"; shift ;; --daily) DAILY=1 ;; --json) JSON=1 ;; *) echo "unknown: $1" >&2; exit 2 ;; esac; shift; done
[[ "$SINCE" =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}$ ]] || { echo "--since YYYY-MM-DD" >&2; exit 2; }
# psql/pg_dump reject Prisma-only URL parameters (connection_limit, schema, ...): strip them.
pgurl() { sed -E 's/([?&])(connection_limit|pool_timeout|schema|pgbouncer|socket_timeout|statement_cache_size)=[^&]*/\1/g; s/&&+/\&/g; s/\?&/?/; s/[?&]+$//' <<<"$1"; }
URL=$(pgurl "${CYRUS_DATABASE_URL:-${DATABASE_URL:?set CYRUS_DATABASE_URL or DATABASE_URL}}")
SALT="${CYRUS_EXPORT_SALT:-cyrus}"
if [ "$DAILY" = 1 ]; then
  SQL="select date_trunc('day', \"createdAt\")::date as day, count(*) as builds,
         count(*) filter (where status='succeeded') as succeeded, count(*) filter (where status='failed') as failed,
         round(sum(\"costUsd\")::numeric, 4) as cost_usd, round(avg(\"costUsd\")::numeric, 4) as avg_cost_usd,
         round((percentile_cont(0.95) within group (order by \"costUsd\"))::numeric, 4) as p95_cost_usd
       from \"ModBuild\" where \"createdAt\" >= '$SINCE' group by 1 order by 1"
else
  SQL="select id, \"createdAt\", \"finishedAt\", status, \"errorCode\", \"mcVersion\", cyrus->>'model' as model, attempts,
         \"durationMs\", \"costUsd\", left(md5('$SALT' || \"userId\"), 16) as user_hash
       from \"ModBuild\" where \"createdAt\" >= '$SINCE' order by \"createdAt\""
fi
SQL=$(tr '\n' ' ' <<<"$SQL")
if [ "$JSON" = 1 ]; then psql "$URL" -XAtq -c "select coalesce(json_agg(r), '[]') from ($SQL) r"
