  goodBaseId: string | null;
  regressionVsGood: Regression | null;
  /** Succeeded, not reworked, not a major regression (vs base or vs the last good build). */
  kept: boolean;
};

export type LearningOptions = {
  /** Rework window (minutes). Default 30. */
  reworkMinutes?: number;
  /** Surfaces taken from jars (build id -> surface); overrides the surface derived from the result. */
  surfaces?: Record<string, Surface>;
};
