// Cyrus LEARNING LOOP: the player-visible surface of a build (classes, commands, config keys) and the diff between two.
// Pure. Reads ModBuild.result (files[], commands[], config[]) or a jar listing; never file contents.
import type { Regression, Surface } from "./types";

const rec = (v: unknown): Record<string, unknown> => (v && typeof v === "object" && !Array.isArray(v) ? (v as Record<string, unknown>) : {});
const arr = (v: unknown): unknown[] => (Array.isArray(v) ? v : []);
const uniqSorted = (a: string[]) => [...new Set(a)].sort();

/** "src/main/java/dev/nxeon/plugins/x/Foo.java" -> "dev.nxeon.plugins.x.Foo"; null for anything that is not a Java source. */
export function classOfPath(p: string): string | null {
  const m = /(?:^|\/)(?:src\/main\/java\/)?((?:[A-Za-z_][\w$]*\/)*[A-Za-z_][\w$]*)\.java$/.exec(p.replace(/\\/g, "/"));
  return m ? m[1].replace(/\//g, ".") : null;
}

/**
 * Command surface from usage texts such as "/chunkmirror <on|off|status|reload>", "/chunkmirror give <item> [player]" or
 * "/chunkmirror on". Yields "/chunkmirror" plus "/chunkmirror on" for each literal word that follows the label.
 */
export function commandsOfUsage(usages: string[]): string[] {
  const out: string[] = [];
  for (const raw of usages) {
    const u = String(raw || "").trim();
    const m = /^\/?([A-Za-z0-9_:.-]+)\s*(.*)$/.exec(u);
    if (!m) continue;
    const label = "/" + m[1].toLowerCase();
    out.push(label);
    const rest = m[2];
    // a <a|b|c> or [a|b] group of literals, or a bare literal word, but not a <placeholder> with no bar.
    const groups = rest.match(/[<\[][^>\]]*[>\]]|\S+/g) ?? [];
    for (const g of groups.slice(0, 1)) { // only the first slot is the sub-command; later slots are arguments
      const inner = g.replace(/^[<\[]|[>\]]$/g, "");
      const isGroup = /^[<\[]/.test(g);
      const words = inner.split("|").map((w) => w.trim()).filter(Boolean);
      if (isGroup && words.length < 2 && !/^[a-z0-9_-]+$/.test(inner)) continue;
      if (isGroup && words.length === 1 && !g.startsWith("[") && /^(item|player|name|value|target|amount|id|args?)$/i.test(words[0])) continue;
      for (const w of words) if (/^[a-z][a-z0-9_-]*$/i.test(w) && !/^(item|player|name|value|target|amount|id|args?)$/i.test(w) && !(isGroup && words.length === 1)) out.push(`${label} ${w.toLowerCase()}`);
    }
  }
  return uniqSorted(out);
}

/** Surface from a stored ModBuild.result. Config keys are only those the model listed (`result.config[].key`). */
export function surfaceOfResult(result: unknown): Surface {
  const r = rec(result);
  const classes = arr(r.files).map((f) => classOfPath(String(rec(f).path ?? ""))).filter((c): c is string => !!c);
  const commands = commandsOfUsage(arr(r.commands).map((c) => String(rec(c).usage ?? "")));
  const configKeys = arr(r.config).map((c) => String(rec(c).key ?? "")).filter(Boolean);
  return { classes: uniqSorted(classes), commands, configKeys: uniqSorted(configKeys), source: "result" };
}

/** Surface from a jar listing: class names, the plugin.yml command usages, and the dotted keys of config.yml. */
export function surfaceOfJar(input: { classes: string[]; commandUsages: string[]; configKeys: string[] }): Surface {
  return { classes: uniqSorted(input.classes), commands: commandsOfUsage(input.commandUsages), configKeys: uniqSorted(input.configKeys), source: "jar" };
}

/**
 * Dotted keys of a YAML text, indentation-based (comments ignored; list items not followed). Enough for plugin config.yml
 * files; not a YAML parser: anchors, flow maps and multi-line scalars are not interpreted.
 */
export function yamlKeys(text: string): string[] {
  const keys: string[] = [];
  const stack: { indent: number; key: string }[] = [];
  for (const line of String(text).split(/\r?\n/)) {
    if (!line.trim() || /^\s*#/.test(line) || /^\s*-/.test(line)) continue;
    const m = /^(\s*)([A-Za-z0-9_.\-"']+):(\s|$)/.exec(line);
    if (!m) continue;
    const indent = m[1].length;
    const key = m[2].replace(/^["']|["']$/g, "");
    while (stack.length && stack[stack.length - 1].indent >= indent) stack.pop();
    stack.push({ indent, key });
    const hasValue = line.slice(m[0].length).trim() !== "" && !/^\s*#/.test(line.slice(m[0].length));
    if (hasValue) keys.push(stack.map((s) => s.key).join("."));
  }
  return uniqSorted(keys);
}

const MAJOR_CLASS_RATIO = 0.5;

/** What `next` lost relative to `base`. Severity: major = a command or sub-command is gone, or half the classes are; minor = anything else removed. */
export function diffSurface(baseId: string, base: Surface, next: Surface): Regression {
  const gone = (a: string[], b: string[]) => { const s = new Set(b); return a.filter((x) => !s.has(x)); };
  const removedClasses = gone(base.classes, next.classes);
  const removedCommands = gone(base.commands, next.commands);
  const removedConfigKeys = gone(base.configKeys, next.configKeys);
  const configKeysTrusted = base.source === "jar" && next.source === "jar";
  const classRatio = base.classes.length >= 3 ? removedClasses.length / base.classes.length : 0;
  let severity: Regression["severity"] = "none";
  if (removedClasses.length || removedCommands.length || removedConfigKeys.length) severity = "minor";
  if (removedCommands.length > 0 || classRatio >= MAJOR_CLASS_RATIO || (configKeysTrusted && removedConfigKeys.length >= Math.max(3, base.configKeys.length / 2))) severity = "major";
  return { baseId, severity, removedClasses, removedCommands, removedConfigKeys, baseCounts: { classes: base.classes.length, commands: base.commands.length, configKeys: base.configKeys.length }, configKeysTrusted };
}
