// Cyrus LEARNING LOOP step 1: per-build OUTCOME SIGNALS, derived from ModBuild rows and the stored result JSON. Pure.
//
// Signals: rework (the next change on the same lineage within 30 min of this build finishing), regression (the build removed
// classes / commands / config keys that its base, or the last good build of the lineage, had), guard refusal, interruption,
// Test Flight failure, install failure, model tier vs outcome, turns / tokens / cost per lane, cost per success.
// Nothing here reads file contents or user text: see types.ts for the privacy line.
import { diffSurface, surfaceOfResult } from "./surface";
import type { BuildRow, BuildSignals, CallKind, CallSummary, LearningOptions, ModelFamily, Outcome, Regression, Surface } from "./types";

export const REWORK_MINUTES = 30;
/** D-03: 1 Cyrus token = $0.002 of real cost. */
export const USD_PER_TOKEN = 0.002;

const rec = (v: unknown): Record<string, unknown> => (v && typeof v === "object" && !Array.isArray(v) ? (v as Record<string, unknown>) : {});
const arr = (v: unknown): unknown[] => (Array.isArray(v) ? v : []);
const num = (v: unknown): number => (typeof v === "number" && Number.isFinite(v) ? v : 0);
const str = (v: unknown): string | null => (typeof v === "string" && v ? v : null);
const ms = (v: Date | string | number | null | undefined): number | null => {
  if (v == null) return null;
  const t = v instanceof Date ? v.getTime() : typeof v === "number" ? v : Date.parse(v);
  return Number.isFinite(t) ? t : null;
};

export function familyOf(model: string | null | undefined): ModelFamily | null {
  const m = String(model || "").toLowerCase();
  if (!m) return null;
  return m.includes("haiku") ? "haiku" : m.includes("sonnet") ? "sonnet" : m.includes("opus") ? "opus" : "other";
}

const KINDS: CallKind[] = ["guard", "generate", "change", "repair", "repair-asset"];
const kindOf = (k: unknown): CallKind => (KINDS as string[]).includes(String(k)) ? (String(k) as CallKind) : "other";

function outcomeOf(status: string, code: string | null): Outcome {
  if (status === "succeeded") return "success";
  if (code === "refused") return "refused";
  if (code === "interrupted") return "interrupted";
  if (code === "unavailable" || code === "unreachable" || code === "lost") return "unavailable";
  return "failed";
}

function testFlightOf(cyrus: Record<string, unknown>): BuildSignals["testFlight"] {
  const tf = rec(cyrus.testFlight);
  if (!Object.keys(tf).length) return { ran: false, failed: false, failedChecks: [], stress: null };
  const failedChecks = arr(tf.checks).filter((c) => rec(c).status === "fail").map((c) => String(rec(c).id));
  const stress = str(rec(tf.stress).verdict);
  const failed = tf.verdict === "failed" || failedChecks.length > 0 || stress === "fail" || stress === "failed" || tf.state === "gave_up";
  return { ran: tf.state === "done" || tf.state === "gave_up", failed, failedChecks, stress };
}

function installOf(row: BuildRow): BuildSignals["install"] {
  const li = rec(row.lastInstall);
  if (!Object.keys(li).length) return { installed: false, failed: false, replaced: 0 };
  const failed = !!li.error || li.ok === false || li.failed === true;
  return { installed: !failed, failed, replaced: arr(li.replaced).length };
}

function usageOf(calls: unknown[]): BuildSignals["usage"] {
  let any = false;
  const u = { input: 0, cacheWrite: 0, cacheRead: 0, output: 0, toolCalls: 0 };
  for (const c of calls) {
    const t = rec(rec(c).tokens);
    if (!Object.keys(t).length) continue;
    any = true;
    u.input += num(t.uncached ?? t.input); u.cacheWrite += num(t.cacheWrite); u.cacheRead += num(t.cacheRead); u.output += num(t.output);
    u.toolCalls += Object.values(rec(rec(c).toolCalls)).reduce<number>((a, b) => a + num(b), 0);
  }
  return any ? u : null;
}

function promptBucket(row: BuildRow): BuildSignals["promptBucket"] {
  const n = String(row.changeRequest || row.prompt || "").length;
  return n === 0 ? "none" : n < 80 ? "short" : n < 300 ? "medium" : "long";
}

type Pre = { row: BuildRow; sig: BuildSignals; surface: Surface };

function pre(row: BuildRow, opts: LearningOptions): Pre {
  const result = rec(row.result);
  const cyrus = rec(row.cyrus);
  const calls = arr(rec(result.ai).calls);
  const callsByKind: Partial<Record<CallKind, CallSummary>> = {};
  let turns = 0;
  for (const c of calls) {
    const k = kindOf(rec(c).kind);
    const s = (callsByKind[k] ??= { n: 0, turns: 0, costUsd: 0, durationMs: 0 });
    s.n++; s.turns += num(rec(c).turns); s.costUsd += num(rec(c).costUsd); s.durationMs += num(rec(c).durationMs);
    if (k !== "guard") turns += num(rec(c).turns);
  }
  const main = calls.find((c) => ["generate", "change"].includes(String(rec(c).kind))) ?? calls.find((c) => rec(c).kind !== "guard");
  const tier = str(cyrus.model) ?? str(rec(main).route) ?? str(rec(result.ai).route);
  const planned = rec(rec(cyrus.assets).planned);
  const lanes = arr(planned.lanes).map(String).sort();
  const created = ms(row.createdAt) ?? 0;
  const dur = num(row.durationMs);
  const ended = ms(row.finishedAt) ?? (created + dur);
  const costUsd = num(row.costUsd);
  const code = str(row.errorCode);
  const outcome = outcomeOf(row.status, code);
  const refused = outcome === "refused";
  const surface = opts.surfaces?.[row.id] ?? surfaceOfResult(row.result);
  const sig: BuildSignals = {
    id: row.id,
    rootId: row.rootBuildId || row.id,
    baseId: row.baseBuildId || null,
    createdAtMs: created,
    endedAtMs: ended,
    kind: row.baseBuildId ? "change" : "fresh",
    status: row.status,
    outcome,
    tier,
    family: familyOf(str(rec(main).resolvedModel) ?? str(rec(main).model)),
    route: str(rec(result.ai).route),
    routeMethod: str(rec(result.ai).routeMethod),
    lanes,
    laneKey: lanes.length ? lanes.join("+") : "plain",
    promptBucket: promptBucket(row),
    mcVersion: row.mcVersion ?? null,
    attempts: num(row.attempts),
    repairs: num(result.repairs),
    costUsd,
    durationMs: dur,
    turns,
    tokensEst: Math.round(costUsd / USD_PER_TOKEN),
    callsByKind,
    usage: usageOf(calls),
    guardRefusal: refused,
    guardReason: refused ? (/guard:([a-z_-]+)/i.exec(String(rec(result).errorDetail ?? ""))?.[1] ?? null) : null,
    interrupted: outcome === "interrupted",
    unavailable: outcome === "unavailable",
    testFlight: testFlightOf(cyrus),
    install: installOf(row),
    rework: { reworked: false, byId: null, gapMin: null, via: null, wastedUsd: 0 },
    retry: { retried: false, byId: null, gapMin: null },
    regression: null,
    goodBaseId: null,
    regressionVsGood: null,
    kept: false,
  };
  return { row, sig, surface };
}

/**
 * Derive the signals of every build in `rows` (any order; lineages are linked by rootBuildId / baseBuildId). A build is
 * REWORKED when the earliest later change of its lineage that builds on it (or on its base: a discard-and-retry) starts within
 * `reworkMinutes` after it ended; a failed build is RETRIED when the same user re-sends the same text within the window.
 */
export function deriveSignals(rows: BuildRow[], opts: LearningOptions = {}): BuildSignals[] {
  const window = (opts.reworkMinutes ?? REWORK_MINUTES) * 60_000;
  const items = rows.map((r) => pre(r, opts)).sort((a, b) => a.sig.createdAtMs - b.sig.createdAtMs || a.sig.id.localeCompare(b.sig.id));
  const byId = new Map(items.map((p) => [p.sig.id, p]));

  // rework + retry
  for (const p of items) {
    const s = p.sig;
    if (s.outcome === "success") {
      const next = items.find((q) => q.sig.rootId === s.rootId && q.sig.kind === "change" && q.sig.createdAtMs > s.createdAtMs && q.sig.id !== s.id
        && (q.sig.baseId === s.id || (!!s.baseId && q.sig.baseId === s.baseId)) && q.sig.createdAtMs - s.endedAtMs <= window);
      if (next) s.rework = { reworked: true, byId: next.sig.id, gapMin: round1(Math.max(0, next.sig.createdAtMs - s.endedAtMs) / 60_000), via: next.sig.baseId === s.id ? "base" : "sibling", wastedUsd: s.costUsd };
    } else {
      const text = (p.row.changeRequest || p.row.prompt || "").trim();
      const next = text ? items.find((q) => q.sig.createdAtMs > s.createdAtMs && q.row.userId === p.row.userId && (q.row.changeRequest || q.row.prompt || "").trim() === text
        && q.sig.createdAtMs - Math.max(s.endedAtMs, s.createdAtMs) <= window) : undefined;
      if (next) s.retry = { retried: true, byId: next.sig.id, gapMin: round1(Math.max(0, next.sig.createdAtMs - s.endedAtMs) / 60_000) };
    }
  }

  // regression vs base
  for (const p of items) {
    const base = p.sig.baseId ? byId.get(p.sig.baseId) : undefined;
    if (base && p.sig.outcome === "success" && base.sig.outcome === "success") p.sig.regression = diffSurface(base.sig.id, base.surface, p.surface);
  }

  // regression vs the last good build of the lineage
  const goodMemo = new Map<string, boolean>();
  const isGood = (id: string, seen = new Set<string>()): boolean => {
    const p = byId.get(id);
    if (!p || seen.has(id)) return false;
    const memo = goodMemo.get(id);
    if (memo !== undefined) return memo;
    const g = p.sig.outcome === "success" && !p.sig.rework.reworked && p.sig.regression?.severity !== "major";
    goodMemo.set(id, g);
    return g;
  };
  for (const p of items) {
    const seen = new Set<string>([p.sig.id]);
    let cur = p.sig.baseId;
    while (cur && !seen.has(cur)) {
      seen.add(cur);
      if (isGood(cur)) { p.sig.goodBaseId = cur; break; }
      cur = byId.get(cur)?.sig.baseId ?? null;
    }
    const good = p.sig.goodBaseId ? byId.get(p.sig.goodBaseId) : undefined;
    if (good && p.sig.outcome === "success") p.sig.regressionVsGood = diffSurface(good.sig.id, good.surface, p.surface);
    p.sig.kept = p.sig.outcome === "success" && !p.sig.rework.reworked && p.sig.regression?.severity !== "major" && p.sig.regressionVsGood?.severity !== "major";
  }
  return items.map((p) => p.sig);
}

