// Cyrus LEARNING LOOP: aggregate per-build signals into the numbers the report, the mining job and the admin card show. Pure.
import { round4 } from "./signals";
import type { BuildSignals, CallKind, CallSummary } from "./types";

export type Group = {
  key: string;
  builds: number;
  succeeded: number;
  kept: number;
  reworked: number;
  majorRegressions: number;
  costUsd: number;
  turns: number;
  tokensEst: number;
  /** costUsd / succeeded builds (null when none). */
  costPerSuccess: number | null;
  /** costUsd / kept builds: success that was not reworked and not a major regression. */
  costPerKept: number | null;
  avgTurns: number;
  avgCostUsd: number;
};

export type Summary = {
  builds: number;
  succeeded: number;
  failedByCode: Record<string, number>;
  totalCostUsd: number;
  totalTokensEst: number;
  counts: {
    guardRefusals: number; interrupted: number; unavailable: number; testFlightFailures: number; installFailures: number;
    reworked: number; retriedAfterFailure: number; majorRegressions: number; minorRegressions: number; majorVsGood: number; kept: number;
  };
  wasted: { reworkUsd: number; reworkBuilds: number; failedUsd: number; majorRegressionUsd: number };
  byLane: Group[];
  byTier: Group[];
  byFamily: Group[];
  byRoute: Group[];
  byKind: Record<string, CallSummary & { share: number }>;
  byFamilyKind: Record<string, CallSummary>;
  freshVsChange: Group[];
  /** Only builds whose result carried persisted token usage (CYRUS_LEARNING on at sync time). */
  usage: { builds: number; input: number; cacheWrite: number; cacheRead: number; output: number } | null;
};

export function groupBy(sigs: BuildSignals[], keyOf: (s: BuildSignals) => string | null): Group[] {
  const m = new Map<string, BuildSignals[]>();
  for (const s of sigs) { const k = keyOf(s) ?? "unknown"; (m.get(k) ?? m.set(k, []).get(k)!).push(s); }
  return [...m.entries()].map(([key, list]) => {
    const succeeded = list.filter((s) => s.outcome === "success").length;
    const kept = list.filter((s) => s.kept).length;
    const costUsd = list.reduce((a, s) => a + s.costUsd, 0);
    const turns = list.reduce((a, s) => a + s.turns, 0);
    return {
      key, builds: list.length, succeeded, kept,
      reworked: list.filter((s) => s.rework.reworked).length,
      majorRegressions: list.filter((s) => s.regression?.severity === "major" || s.regressionVsGood?.severity === "major").length,
      costUsd: round4(costUsd), turns, tokensEst: list.reduce((a, s) => a + s.tokensEst, 0),
      costPerSuccess: succeeded ? round4(costUsd / succeeded) : null,
      costPerKept: kept ? round4(costUsd / kept) : null,
      avgTurns: Math.round((turns / list.length) * 10) / 10,
      avgCostUsd: round4(costUsd / list.length),
    };
  }).sort((a, b) => b.costUsd - a.costUsd);
}

export function summarize(sigs: BuildSignals[]): Summary {
  const failedByCode: Record<string, number> = {};
  for (const s of sigs) if (s.outcome !== "success") failedByCode[s.outcome] = (failedByCode[s.outcome] ?? 0) + 1;
  const total = sigs.reduce((a, s) => a + s.costUsd, 0);
  const byKind: Summary["byKind"] = {};
  const byFamilyKind: Summary["byFamilyKind"] = {};
  for (const s of sigs) for (const [k, c] of Object.entries(s.callsByKind) as [CallKind, CallSummary][]) {
    const b = (byKind[k] ??= { n: 0, turns: 0, costUsd: 0, durationMs: 0, share: 0 });
    b.n += c.n; b.turns += c.turns; b.costUsd += c.costUsd; b.durationMs += c.durationMs;
    const fk = `${s.family ?? "unknown"}/${k}`;
    const f = (byFamilyKind[fk] ??= { n: 0, turns: 0, costUsd: 0, durationMs: 0 });
    f.n += c.n; f.turns += c.turns; f.costUsd += c.costUsd; f.durationMs += c.durationMs;
  }
  for (const b of Object.values(byKind)) { b.costUsd = round4(b.costUsd); b.share = total ? round4(b.costUsd / total) : 0; }
  for (const f of Object.values(byFamilyKind)) f.costUsd = round4(f.costUsd);
  const withUsage = sigs.filter((s) => s.usage);
  const rework = sigs.filter((s) => s.rework.reworked);
  const major = sigs.filter((s) => s.regression?.severity === "major" || s.regressionVsGood?.severity === "major");
  return {
    builds: sigs.length,
    succeeded: sigs.filter((s) => s.outcome === "success").length,
    failedByCode,
    totalCostUsd: round4(total),
    totalTokensEst: sigs.reduce((a, s) => a + s.tokensEst, 0),
    counts: {
      guardRefusals: sigs.filter((s) => s.guardRefusal).length,
      interrupted: sigs.filter((s) => s.interrupted).length,
      unavailable: sigs.filter((s) => s.unavailable).length,
      testFlightFailures: sigs.filter((s) => s.testFlight.failed).length,
      installFailures: sigs.filter((s) => s.install.failed).length,
      reworked: rework.length,
      retriedAfterFailure: sigs.filter((s) => s.retry.retried).length,
      majorRegressions: sigs.filter((s) => s.regression?.severity === "major").length,
      minorRegressions: sigs.filter((s) => s.regression?.severity === "minor").length,
      majorVsGood: sigs.filter((s) => s.regressionVsGood?.severity === "major").length,
      kept: sigs.filter((s) => s.kept).length,
    },
    wasted: {
      reworkUsd: round4(rework.reduce((a, s) => a + s.rework.wastedUsd, 0)),
      reworkBuilds: rework.length,
      failedUsd: round4(sigs.filter((s) => s.outcome !== "success").reduce((a, s) => a + s.costUsd, 0)),
      majorRegressionUsd: round4(major.reduce((a, s) => a + s.costUsd, 0)),
    },
    byLane: groupBy(sigs, (s) => s.laneKey),
    byTier: groupBy(sigs, (s) => s.tier),
    byFamily: groupBy(sigs, (s) => s.family),
    byRoute: groupBy(sigs, (s) => s.route ?? "none"),
    byKind,
    byFamilyKind,
    freshVsChange: groupBy(sigs, (s) => s.kind),
    usage: withUsage.length ? {
      builds: withUsage.length,
      input: withUsage.reduce((a, s) => a + s.usage!.input, 0), cacheWrite: withUsage.reduce((a, s) => a + s.usage!.cacheWrite, 0),
      cacheRead: withUsage.reduce((a, s) => a + s.usage!.cacheRead, 0), output: withUsage.reduce((a, s) => a + s.usage!.output, 0),
    } : null,
  };
}
