cd /tank/dev-worktrees/cyrus-learning && cat > test/cyrus-learning-signals.test.ts <<'EOF'
// Learning loop step 1: outcome signals. Golden fixture = the 27 real production ModBuild rows of 2026-10-12 (all the owner's),
// including the ChunkMirror lineage: v1.3.0 was good, then two rework builds lost the mod (the Spawner Wand build and the Haiku
// bolt-on). No AI, no database, no network.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { classOfPath, commandsOfUsage, diffSurface, surfaceOfJar, surfaceOfResult, yamlKeys } from "../lib/cyrus/learning/surface";
import { deriveSignals, familyOf, REWORK_MINUTES } from "../lib/cyrus/learning/signals";
import { summarize } from "../lib/cyrus/learning/aggregate";
import type { BuildRow, Surface } from "../lib/cyrus/learning/types";
import { LINEAGE as L, jarFixtures, prodRows } from "./fixtures/cyrus-learning/rows";

const sigsOf = () => Object.fromEntries(deriveSignals(prodRows()).map((s) => [s.id, s]));

describe("surface", () => {
  it("class names come from Java source paths only", () => {
    assert.equal(classOfPath("src/main/java/dev/nxeon/plugins/x/Foo.java"), "dev.nxeon.plugins.x.Foo");
    assert.equal(classOfPath("dev/nxeon/Foo.java"), "dev.nxeon.Foo");
    assert.equal(classOfPath("build.gradle.kts"), null);
    assert.equal(classOfPath("assets/designs/spawner_wand.json"), null);
  });
  it("commands: label plus literal sub-commands, never placeholders or later arguments", () => {
    assert.deepEqual(commandsOfUsage(["/chunkmirror <on|off|status|reload>"]), ["/chunkmirror", "/chunkmirror off", "/chunkmirror on", "/chunkmirror reload", "/chunkmirror status"]);
    assert.deepEqual(commandsOfUsage(["/chunkmirror give <item> [player]", "/chunkmirror list"]), ["/chunkmirror", "/chunkmirror give", "/chunkmirror list"]);
    assert.deepEqual(commandsOfUsage(["/home <name>", "/placeholderinfo", "/warp [name]"]), ["/home", "/placeholderinfo", "/warp"]);
    assert.deepEqual(commandsOfUsage(["/x [a|b]"]), ["/x", "/x a", "/x b"]);
  });
  it("yamlKeys: dotted leaf keys, comments and list items ignored", () => {
    const y = "# c\nenabled: true\nperf:\n  max-radius: 48\n  nested:\n    deep: 1 # trailing\nitems:\n  a:\n    - x\nlist: [1, 2]\n";
    assert.deepEqual(yamlKeys(y), ["enabled", "list", "perf.max-radius", "perf.nested.deep"]);
  });
  it("diffSurface severity: a lost command or half the classes is major; config keys alone are minor unless both sides are jar-derived", () => {
    const s = (o: Partial<Surface>): Surface => ({ classes: ["a.A", "a.B", "a.C", "a.D"], commands: ["/c"], configKeys: ["k1", "k2", "k3", "k4"], source: "result", ...o });
    assert.equal(diffSurface("b", s({}), s({})).severity, "none");
    assert.equal(diffSurface("b", s({}), s({ classes: ["a.A", "a.B", "a.C"] })).severity, "minor");
    assert.equal(diffSurface("b", s({}), s({ classes: ["a.A", "a.B"] })).severity, "major");
    assert.equal(diffSurface("b", s({}), s({ commands: [] })).severity, "major");
    assert.equal(diffSurface("b", s({}), s({ configKeys: [] })).severity, "minor");
    assert.equal(diffSurface("b", s({ source: "jar" }), s({ source: "jar", configKeys: [] })).severity, "major");
  });
  it("surfaceOfResult reads files, commands and config keys of a stored result", () => {
    const sf = surfaceOfResult({ files: [{ path: "src/main/java/p/A.java" }, { path: "plugin.yml" }], commands: [{ usage: "/a <x|y>" }], config: [{ key: "k.v" }] });
    assert.deepEqual(sf, { classes: ["p.A"], commands: ["/a", "/a x", "/a y"], configKeys: ["k.v"], source: "result" });
  });
});

describe("rework, retry and refusal", () => {
  const row = (id: string, createdMin: number, over: Partial<BuildRow> = {}): BuildRow => ({
    id, userId: "u", status: "succeeded", prompt: "p", rootBuildId: "r", baseBuildId: id === "r" ? null : "r", costUsd: 0.1, durationMs: 60_000,
    createdAt: Date.UTC(2026, 9, 12, 0, createdMin), finishedAt: Date.UTC(2026, 9, 12, 0, createdMin + 1), ...over,
  });
  it("a follow-up change within 30 minutes of the build ending is rework; at 31 it is not", () => {
    const a = deriveSignals([row("r", 0), row("c1", 1 + REWORK_MINUTES)]).find((s) => s.id === "r")!;
    assert.equal(a.rework.reworked, true);
    assert.equal(a.rework.byId, "c1");
    assert.equal(a.rework.wastedUsd, 0.1);
    const b = deriveSignals([row("r", 0), row("c1", 2 + REWORK_MINUTES)]).find((s) => s.id === "r")!;
    assert.equal(b.rework.reworked, false);
    assert.equal(deriveSignals([row("r", 0), row("c1", 60)], { reworkMinutes: 90 }).find((s) => s.id === "r")!.rework.reworked, true);
  });
  it("a discard-and-retry from the same base counts as rework of the sibling", () => {
    const s = deriveSignals([row("r", 0), row("x", 10, { rootBuildId: "r", baseBuildId: "r" }), row("y", 15, { rootBuildId: "r", baseBuildId: "r" })]);
    const x = s.find((q) => q.id === "x")!;
    assert.equal(x.rework.reworked, true);
    assert.equal(x.rework.via, "sibling");
  });
  it("a failed build re-sent word for word by the same user within the window is a retry", () => {
    const rows = [row("f", 0, { status: "failed", errorCode: "interrupted", rootBuildId: "f", baseBuildId: null }), row("g", 4, { rootBuildId: "g", baseBuildId: null })];
    const f = deriveSignals(rows).find((q) => q.id === "f")!;
    assert.equal(f.outcome, "interrupted");
    assert.equal(f.interrupted, true);
    assert.deepEqual([f.retry.retried, f.retry.byId], [true, "g"]);
    assert.equal(deriveSignals([rows[0], { ...rows[1], prompt: "different" }]).find((q) => q.id === "f")!.retry.retried, false);
