// Cyrus LEARNING LOOP step 2: concrete token-saving levers with a saving estimate (a low-high range in USD over the sample), a
// risk grade and a plain statement of the evidence. Pure. These are ESTIMATES from the build records plus the measured shapes
// in docs/DOCUMENTATION.md "AI Mod Builder: efficiency (service 0.5)"; ModBuild stores no token counts today, so every range
// carries its assumption. Nothing here changes a prompt, a sheet, a route or a flag: it ranks ideas for the owner.
import type { BuildSignals } from "./types";
import { round4 } from "./signals";

export type Risk = "low" | "medium" | "high";
export type Lever = {
  id: string;
  title: string;
  /** What would change (a flag, a route table, a service setting) and who decides. */
  change: string;
  affectedUsd: number;
  savingUsd: { low: number; high: number };
  /** Mid saving as a share of all spend in the sample. */
  savingPct: number;
  risk: Risk;
  /** high / medium / low confidence in the range (low = assumed percentages, no direct measurement). */
  confidence: "high" | "medium" | "low";
  basis: string;
  /** Mid saving divided by the risk weight; the sort key. */
  score: number;
};

const RISK_WEIGHT: Record<Risk, number> = { low: 1, medium: 1.6, high: 3 };
/** List prices in USD per million input tokens (cache read is 0.1x). docs efficiency notes, 2026-10-08. */
export const INPUT_PRICE_PER_M: Record<string, number> = { haiku: 1, sonnet: 2, opus: 5, other: 2 };

export type LeverContext = {
  /** Bytes of the version sheet in the system prefix (services/modbuilder/sheets/<v>.md); ~4 bytes per token. */
  sheetBytes?: number;
};

const sum = (a: number[]) => a.reduce((x, y) => x + y, 0);
const spendOf = (list: BuildSignals[], kinds: string[]) => sum(list.map((s) => sum(kinds.map((k) => (s.callsByKind as Record<string, { costUsd: number } | undefined>)[k]?.costUsd ?? 0))));

function lever(total: number, l: Omit<Lever, "savingPct" | "score" | "savingUsd"> & { range: [number, number] }): Lever {
  const { range, ...rest } = l;
  const low = round4(l.affectedUsd * range[0]);
  const high = round4(l.affectedUsd * range[1]);
  const mid = (low + high) / 2;
  return { ...rest, savingUsd: { low, high }, savingPct: total ? round4(mid / total) : 0, score: round4(mid / RISK_WEIGHT[l.risk]) };
}

export function computeLevers(sigs: BuildSignals[], ctx: LeverContext = {}): Lever[] {
  const total = sum(sigs.map((s) => s.costUsd));
  const out: Lever[] = [];
  const changeBuilds = sigs.filter((s) => s.kind === "change" && s.outcome === "success");

  // 1. Saka on Sonnet 5.5 (MB_TIER_SAKA). Measured offline eval: $0.203 -> $0.104 per build (-49%), first try 93% -> 100%.
  const saka = sigs.filter((s) => s.tier === "saka");
  out.push(lever(total, {
    id: "saka-sonnet-5-5", title: "Run the Saka tier on Sonnet 5.5", change: "service env MB_TIER_SAKA=claude-sonnet-5-5 (owner decision; eval first)",
    affectedUsd: sum(saka.map((s) => s.costUsd)), range: [0.35, 0.5], risk: "medium", confidence: "medium",
    basis: "Measured on fresh builds in the 0.3 eval (same 28 prompts: -49% cost, first try 93% to 100%). Change builds were not measured; the low end assumes they save less.",
