  const regressed = sigs.filter((s) => s.regression?.severity === "major" || s.regressionVsGood?.severity === "major");
  out.push(lever(total, {
    id: "regression-guard", title: "Regression guard on change builds (a lost command or most of the classes triggers one repair turn or a warning)", change: "build service / portal check using lib/cyrus/learning/surface.ts; behind a flag (branch fix/cyrus-change-regression-guards)",
