    affectedUsd: spendOf(changeCalls, ["change"]), range: [0.1, 0.2], risk: "low", confidence: "low",
    basis: `Change builds averaged ${avg(changeCalls.map((s) => s.callsByKind.change?.turns ?? 0)).toFixed(1)} turns against ${avg(sigs.filter((s) => s.kind === "fresh" && s.outcome === "success").map((s) => s.turns)).toFixed(1)} for fresh builds. The 10-20% range is the efficiency note's estimate for the tiers when batching is followed.`,
  }));

  // 5. Effort medium (MB_EFFORT).
  const bigModels = sigs.filter((s) => s.family === "sonnet" || s.family === "opus");
  out.push(lever(total, {
    id: "effort-medium", title: "Medium thinking effort on Sonnet and Opus builds", change: "service env MB_EFFORT=medium (same value on every call of a build; owner decision; eval first)",
    affectedUsd: sum(bigModels.map((s) => s.costUsd)), range: [0.1, 0.2], risk: "medium", confidence: "low",
    basis: "Thinking is 37-77% of output on these tiers (efficiency analysis). The range assumes medium effort halves part of it. Quality impact unmeasured.",
  }));

  // 6. Targeted route floor: no Haiku on a change to a large plugin.
  const haikuChange = sigs.filter((s) => s.kind === "change" && s.family === "haiku");
  const risky = haikuChange.filter((s) => (s.regression?.baseCounts.classes ?? 0) >= 10 || s.lanes.length > 0 || (s.regressionVsGood?.baseCounts.classes ?? 0) >= 10);
  const avgSonnetChange = avg(sigs.filter((s) => s.kind === "change" && s.family === "sonnet" && s.outcome === "success").map((s) => s.costUsd));
  const extra = sum(risky.map((s) => Math.max(0, avgSonnetChange - s.costUsd)));
  const waste = sum(risky.filter((s) => s.rework.reworked || s.regression?.severity === "major" || s.regressionVsGood?.severity === "major").map((s) => s.costUsd));
  out.push(lever(total, {
    id: "route-floor-large-changes", title: "Route floor: a change to a large or designer plugin never runs on Haiku", change: "router (services/modbuilder/route.js or the portal tier choice); owner decision",
    affectedUsd: waste, range: [Math.max(0, (waste - extra) / Math.max(waste, 1e-9)), Math.max(0, (waste * 1.5 - extra) / Math.max(waste, 1e-9))], risk: "low", confidence: "low",
    basis: `${risky.length} Haiku change build(s) touched a plugin with >= 10 classes or a planned lane; $${waste.toFixed(2)} of them was wasted (reworked or regressed); running them on Sonnet costs about $${extra.toFixed(2)} more. A blanket floor on all ${haikuChange.length} Haiku change builds would cost about $${sum(haikuChange.map((s) => Math.max(0, avgSonnetChange - s.costUsd))).toFixed(2)} more and is NOT recommended on this sample.`,
  }));

  // 7. Repairs: cap the asset-repair loop and keep the deterministic autofix first.
  const rep = sigs.filter((s) => s.callsByKind.repair || s.callsByKind["repair-asset"]);
  out.push(lever(total, {
    id: "repair-caps", title: "Retry caps on repairs (asset repairs especially)", change: "service env MB_MAX_TURNS_REPAIR and an asset-repair cap",
    affectedUsd: spendOf(rep, ["repair", "repair-asset"]), range: [0.15, 0.4], risk: "low", confidence: "low",
    basis: `Repairs are ${(100 * spendOf(sigs, ["repair", "repair-asset"]) / Math.max(total, 1e-9)).toFixed(0)}% of spend; the repair-asset call of the Spawner Wand build cost $0.18 for 3 turns. The 0.5 service already caps repair turns at 25.`,
  }));

  // 8. Slimmer version sheets. Cached at 0.1x already, so the pool is small.
  if (ctx.sheetBytes) {
    const tokens = ctx.sheetBytes / 4;
    const pool = sum(sigs.map((s) => sum(Object.entries(s.callsByKind).filter(([k]) => k !== "guard").map(([, c]) => c.turns)) * tokens * (INPUT_PRICE_PER_M[s.family ?? "other"] * 0.1) / 1e6));
    out.push(lever(total, {
      id: "slim-sheets", title: "Smaller version sheets per lane", change: "service sheets (eval first; the 0.5 analysis rejected slicing because a missed section is the failure the sheets fixed)",
      affectedUsd: round4(pool), range: [0.3, 0.5], risk: "high", confidence: "medium",
      basis: `The sheet is about ${Math.round(tokens)} tokens, already cached; this is its cache-read cost over every non-guard turn. Slicing it varies the cached prefix (cache writes cost 12-20x a read).`,
    }));
  }
  return out.sort((a, b) => b.score - a.score);
}

const avg = (a: number[]) => (a.length ? sum(a) / a.length : 0);
