// Cyrus LEARNING LOOP step 3: the MINING JOB's pure core. Clusters failed / reworked / regressed builds into CANDIDATE items for a
// human to review. It never writes to a rule file, a sheet, a prompt or a router: output is data (candidates.jsonl + a review page),
// every item has status "candidate" and carries the build ids it came from.
//
// Kinds: failure-rule (a compile / Test Flight failure pattern), sheet-fact (an API fact the sheet seems to lack),
// golden-case (a request that must keep working), routing-rule (which tier may take which change), prompt-coach-gap (the
// planner / guard / coach should have asked or warned).
import { createHash } from "node:crypto";
import type { BuildSignals } from "./types";

export const CANDIDATE_KINDS = ["failure-rule", "sheet-fact", "golden-case", "routing-rule", "prompt-coach-gap"] as const;
export type CandidateKind = (typeof CANDIDATE_KINDS)[number];

export type Candidate = {
  id: string;
  kind: CandidateKind;
  title: string;
  /** Build ids (ModBuild.id) the item was derived from. Never user text. */
  evidence: string[];
  proposedText: string;
  /** 0..1: more independent builds, a rework or a regression that confirms it, and an owner-visible loss raise it. */
  confidence: number;
  rationale: string;
  status: "candidate";
  /** Which signal produced it (so a reviewer can re-derive it). */
  signal: string;
};

/** Optional text the job may attach when asked (--include-prompts). The default run passes none and no user text is read. */
export type MiningText = { changeRequest?: string | null };
export type MiningOptions = {
  /** Build id -> text, only when the operator opted in. */
  text?: Record<string, MiningText>;
  /** A pattern is a candidate from this many independent builds (default 1: a single owner-visible loss is enough to review). */
  minEvidence?: number;
};

const CORRECTION = /\b(doesn'?t|does not|didn'?t|still|again|not working|isn'?t|broken|wrong|instead|should(?:n'?t)?|only|no longer|stopped|missing|but)\b/i;

export const candidateId = (kind: string, title: string) => createHash("sha256").update(`${kind}\n${title}`).digest("hex").slice(0, 12);
const clamp = (n: number) => Math.max(0.05, Math.min(0.95, Math.round(n * 100) / 100));
const ids = (l: BuildSignals[]) => l.map((s) => s.id);
const list = (a: string[], n = 6) => (a.length > n ? a.slice(0, n).join(", ") + `, +${a.length - n} more` : a.join(", ")) || "(none)";

function make(kind: CandidateKind, title: string, evidence: string[], proposedText: string, confidence: number, rationale: string, signal: string): Candidate {
  return { id: candidateId(kind, title), kind, title, evidence: [...new Set(evidence)], proposedText, confidence: clamp(confidence), rationale, status: "candidate", signal };
}

/** Normalise a compiler / flight message to its shape so repeats cluster: digits, quoted names, paths and identifiers go. */
export function errorShape(msg: string): string {
  return msg.toLowerCase().replace(/[a-z0-9_./-]+\.(java|yml|json|class)(:\d+)?/g, "<file>").replace(/'[^']*'|"[^"]*"/g, "<q>").replace(/\b[a-z_]*[0-9]+[a-z0-9_]*\b/g, "<n>").replace(/\s+/g, " ").trim().slice(0, 120);
}

export function mineCandidates(sigs: BuildSignals[], opts: MiningOptions = {}): Candidate[] {
  const out: Candidate[] = [];
  const min = opts.minEvidence ?? 1;
  const byId = new Map(sigs.map((s) => [s.id, s]));
  const text = (id: string) => opts.text?.[id]?.changeRequest ?? null;

  // 1. Regressions: a change build removed commands / classes that its base (or the last good build) had.
  const reg = sigs.filter((s) => s.regression?.severity === "major" || s.regressionVsGood?.severity === "major");
  for (const s of reg) {
    const r = s.regression?.severity === "major" ? s.regression : s.regressionVsGood!;
    const confirmed = s.rework.reworked || r === s.regression;
    out.push(make("golden-case", `Change keeps the base's commands and classes (${s.id.slice(0, 10)})`, [s.id, r.baseId],
      JSON.stringify({ case: "change-keeps-surface", baseBuild: r.baseId, changeBuild: s.id, mustKeepCommands: r.removedCommands, mustKeepClasses: r.removedClasses.slice(0, 12), note: "a change request that does not ask for removal must not drop these" }),
      0.5 + (confirmed ? 0.2 : 0) + (r.removedCommands.length ? 0.1 : 0), `Build ${s.id} removed ${r.removedCommands.length} command(s) and ${r.removedClasses.length}/${r.baseCounts.classes} class(es) of ${r.baseId}${s.rework.reworked ? `, and was followed by another change ${s.rework.gapMin} min later` : ""}.`, "regression"));
    out.push(make("prompt-coach-gap", `Plan must say what a change removes (${s.id.slice(0, 10)})`, [s.id, r.baseId],
      `Before a change build starts, show the plan's "keeps / replaces / removes" list built from the base build's commands (${list(r.removedCommands)}) and classes; ask when a planned lane would replace the main class${s.lanes.length ? ` (planned lanes: ${s.lanes.join(", ")})` : ""}.`,
      0.45 + (confirmed ? 0.2 : 0), `The change replaced the plugin instead of extending it; the customer found out after installing.`, "regression"));
  }

