cd /tank/dev-worktrees/cyrus-learning/lib/cyrus/learning && cat > release-manifest.ts <<'EOF'
// Cyrus LEARNING LOOP step 3b: the ENGINE RELEASE MANIFEST (idea from GAPS-AND-IDEAS.md: "treat prompt + sheets + rules + scanner +
// image as one engine release, canary, auto-rollback on eval regression"). One record names every part of the engine that ships
// together, the eval baseline it was measured against, the learning candidates it contains and the release to roll back to.
//
// This is a PURE module: it builds, validates and compares manifests. It is NOT wired to a deploy, a router or a flag. Per-build
// records (lib/cyrus/engine-core/release.ts EngineRelease) say which engine made ONE build; this manifest says what a release IS,
// so a build's `engineRelease.id` can later be looked up in the list of manifests.
import { createHash } from "node:crypto";

export const MANIFEST_SCHEMA = 1 as const;
const SHA = /^[0-9a-f]{64}$/;

export type ManifestComponents = {
  /** Base prompt version and the section prompt versions (e.g. design). */
  prompts: { base: string; sections: Record<string, string> };
  /** Version sheets by file name with their sha256. */
  sheets: { name: string; sha256: string }[];
  rules: { version: string; sha256: string };
  scanner: { profile: string; sha256: string };
  /** Build-service image: tag always, digest when known. */
  image: { name: string; tag: string; digest?: string };
  jdk?: string;
  toolchain?: string;
};

export type EvalBaselineRef = {
  /** Where the accepted baseline lives (e.g. services/modbuilder/eval/baseline.json) and its hash at acceptance. */
  file: string;
  sha256: string;
  finalPassPct: number | null;
  builds: number;
  acceptedAt: string;
};

export type ReleaseStatus = "draft" | "canary" | "live" | "rolled-back" | "superseded";

export type ReleaseManifest = {
  schema: typeof MANIFEST_SCHEMA;
  /** er-<16 hex>: a hash of `components` only, so two manifests with the same parts have the same id. */
  id: string;
  createdAt: string;
  status: ReleaseStatus;
  components: ManifestComponents;
  evalBaseline: EvalBaselineRef | null;
  /** Learning candidates (lib/cyrus/learning/mining.ts ids) accepted into this release, for the audit trail. */
  candidates: string[];
  rollback: { toReleaseId: string | null; how: string } | null;
  notes: string;
};

export type ManifestInput = {
  components: ManifestComponents;
  evalBaseline?: EvalBaselineRef | null;
  candidates?: string[];
  rollbackTo?: string | null;
  rollbackHow?: string;
  status?: ReleaseStatus;
  notes?: string;
  now?: Date;
};

const sortObject = <T>(o: Record<string, T>): Record<string, T> => Object.fromEntries(Object.entries(o).sort(([a], [b]) => a.localeCompare(b)));

/** Canonical form: sheets sorted by name, section prompts sorted by key. The id and every comparison use it. */
export function canonicalComponents(c: ManifestComponents): ManifestComponents {
  return { ...c, prompts: { base: c.prompts.base, sections: sortObject(c.prompts.sections) }, sheets: [...c.sheets].sort((a, b) => a.name.localeCompare(b.name)) };
}

export function releaseId(c: ManifestComponents): string {
  return "er-" + createHash("sha256").update(JSON.stringify(canonicalComponents(c))).digest("hex").slice(0, 16);
}

export function createManifest(input: ManifestInput): ReleaseManifest {
  const components = canonicalComponents(input.components);
  const m: ReleaseManifest = {
    schema: MANIFEST_SCHEMA,
    id: releaseId(components),
    createdAt: (input.now ?? new Date()).toISOString(),
    status: input.status ?? "draft",
    components,
    evalBaseline: input.evalBaseline ?? null,
    candidates: [...new Set(input.candidates ?? [])].sort(),
    rollback: input.rollbackTo !== undefined || input.rollbackHow ? { toReleaseId: input.rollbackTo ?? null, how: input.rollbackHow ?? "" } : null,
    notes: input.notes ?? "",
  };
  return m;
}

/** Problems that make a manifest unfit to ship; empty = valid. A `live` / `canary` manifest needs an eval baseline and a rollback pointer. */
export function validateManifest(m: ReleaseManifest): string[] {
  const p: string[] = [];
  if (m.schema !== MANIFEST_SCHEMA) p.push(`schema must be ${MANIFEST_SCHEMA}`);
  if (m.id !== releaseId(m.components)) p.push("id does not match the components (edited by hand?)");
  const c = m.components;
  if (!c.prompts?.base) p.push("prompts.base is missing");
  if (!c.sheets?.length) p.push("no version sheets");
  for (const s of c.sheets ?? []) if (!SHA.test(s.sha256)) p.push(`sheet ${s.name}: sha256 is not 64 hex`);
  if (!c.rules?.version || !SHA.test(c.rules.sha256 ?? "")) p.push("rules need a version and a 64-hex sha256");
  if (!c.scanner?.profile || !SHA.test(c.scanner.sha256 ?? "")) p.push("scanner needs a profile and a 64-hex sha256");
  if (!c.image?.name || !c.image?.tag) p.push("image needs a name and a tag");
  if (c.image?.digest && !/^sha256:[0-9a-f]{64}$/.test(c.image.digest)) p.push("image.digest must be sha256:<64 hex>");
  if (m.evalBaseline && !SHA.test(m.evalBaseline.sha256)) p.push("evalBaseline.sha256 is not 64 hex");
  if (m.status === "live" || m.status === "canary") {
    if (!m.evalBaseline) p.push(`a ${m.status} release needs an eval baseline reference`);
    if (!m.rollback || !m.rollback.how) p.push(`a ${m.status} release needs a rollback pointer`);
    if (m.rollback && m.rollback.toReleaseId === m.id) p.push("rollback points at itself");
  }
  return p;
}

export type ManifestDiff = { changed: string[]; sheets: { added: string[]; removed: string[]; changed: string[] }; same: boolean };

/** Which parts differ between two releases (for the review page and the canary note). */
export function diffManifests(a: ReleaseManifest, b: ReleaseManifest): ManifestDiff {
  const ca = canonicalComponents(a.components), cb = canonicalComponents(b.components);
  const changed: string[] = [];
  if (ca.prompts.base !== cb.prompts.base) changed.push("prompts.base");
  for (const k of new Set([...Object.keys(ca.prompts.sections), ...Object.keys(cb.prompts.sections)])) if (ca.prompts.sections[k] !== cb.prompts.sections[k]) changed.push(`prompts.sections.${k}`);
  if (ca.rules.version !== cb.rules.version || ca.rules.sha256 !== cb.rules.sha256) changed.push("rules");
  if (ca.scanner.sha256 !== cb.scanner.sha256 || ca.scanner.profile !== cb.scanner.profile) changed.push("scanner");
  if (ca.image.tag !== cb.image.tag || ca.image.digest !== cb.image.digest || ca.image.name !== cb.image.name) changed.push("image");
  if (ca.jdk !== cb.jdk) changed.push("jdk");
  if (ca.toolchain !== cb.toolchain) changed.push("toolchain");
  const am = new Map(ca.sheets.map((s) => [s.name, s.sha256])), bm = new Map(cb.sheets.map((s) => [s.name, s.sha256]));
  const sheets = {
    added: [...bm.keys()].filter((k) => !am.has(k)),
    removed: [...am.keys()].filter((k) => !bm.has(k)),
    changed: [...bm.keys()].filter((k) => am.has(k) && am.get(k) !== bm.get(k)),
  };
  if (sheets.added.length || sheets.removed.length || sheets.changed.length) changed.push("sheets");
  return { changed, sheets, same: changed.length === 0 };
}

/** Eval gate: a release may only be promoted when its pass rate does not fall more than `tolerancePct` below the baseline it replaces. */
export function evalGate(previous: EvalBaselineRef | null, next: EvalBaselineRef | null, tolerancePct = 1): { ok: boolean; reason: string } {
  if (!next || next.finalPassPct == null) return { ok: false, reason: "the new release has no eval result" };
  if (!previous || previous.finalPassPct == null) return { ok: true, reason: "no previous baseline to compare with" };
  const drop = previous.finalPassPct - next.finalPassPct;
  return drop > tolerancePct ? { ok: false, reason: `pass rate fell ${drop.toFixed(1)} points (${previous.finalPassPct} to ${next.finalPassPct}), more than the ${tolerancePct} allowed` } : { ok: true, reason: `pass rate ${previous.finalPassPct} to ${next.finalPassPct}` };
}

/** Rollback target of a release, or null when it has none / points at an unknown release. */
export function rollbackTarget(m: ReleaseManifest, all: ReleaseManifest[]): ReleaseManifest | null {
  const id = m.rollback?.toReleaseId;
  return id ? all.find((x) => x.id === id) ?? null : null;
}
