  if (ca.rules.version !== cb.rules.version || ca.rules.sha256 !== cb.rules.sha256) changed.push("rules");
  if (ca.scanner.sha256 !== cb.scanner.sha256 || ca.scanner.profile !== cb.scanner.profile) changed.push("scanner");
  if (ca.image.tag !== cb.image.tag || ca.image.digest !== cb.image.digest || ca.image.name !== cb.image.name) changed.push("image");
  if (ca.jdk !== cb.jdk) changed.push("jdk");
  if (ca.toolchain !== cb.toolchain) changed.push("toolchain");
  const am = new Map(ca.sheets.map((s) => [s.name, s.sha256])), bm = new Map(cb.sheets.map((s) => [s.name, s.sha256]));
  const sheets = {
    added: [...bm.keys()].filter((k) => !am.has(k)),
    removed: [...am.keys()].filter((k) => !bm.has(k)),
    changed: [...bm.keys()].filter((k) => am.has(k) && am.get(k) !== bm.get(k)),
  };
  if (sheets.added.length || sheets.removed.length || sheets.changed.length) changed.push("sheets");
  return { changed, sheets, same: changed.length === 0 };
}

/** Eval gate: a release may only be promoted when its pass rate does not fall more than `tolerancePct` below the baseline it replaces. */
export function evalGate(previous: EvalBaselineRef | null, next: EvalBaselineRef | null, tolerancePct = 1): { ok: boolean; reason: string } {
  if (!next || next.finalPassPct == null) return { ok: false, reason: "the new release has no eval result" };
  if (!previous || previous.finalPassPct == null) return { ok: true, reason: "no previous baseline to compare with" };
  const drop = previous.finalPassPct - next.finalPassPct;
  return drop > tolerancePct ? { ok: false, reason: `pass rate fell ${drop.toFixed(1)} points (${previous.finalPassPct} to ${next.finalPassPct}), more than the ${tolerancePct} allowed` } : { ok: true, reason: `pass rate ${previous.finalPassPct} to ${next.finalPassPct}` };
}

/** Rollback target of a release, or null when it has none / points at an unknown release. */
export function rollbackTarget(m: ReleaseManifest, all: ReleaseManifest[]): ReleaseManifest | null {
  const id = m.rollback?.toReleaseId;
  return id ? all.find((x) => x.id === id) ?? null : null;
}
