// Learning loop steps 2-3: token levers, candidate mining and the engine release manifest. Pure; the production fixture is the
// 27 real ModBuild rows of 2026-10-12. No AI, no database, no network.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { deriveSignals } from "../lib/cyrus/learning/signals";
import { summarize } from "../lib/cyrus/learning/aggregate";
import { computeLevers } from "../lib/cyrus/learning/levers";
import { CANDIDATE_KINDS, candidateId, mineCandidates, parseJsonl, reviewMarkdown, toJsonl } from "../lib/cyrus/learning/mining";
import { createManifest, diffManifests, evalGate, releaseId, rollbackTarget, validateManifest, type ManifestComponents } from "../lib/cyrus/learning/release-manifest";
import { learningEnabled } from "../lib/cyrus/learning";
import { LINEAGE as L, prodRows } from "./fixtures/cyrus-learning/rows";

