    assert.ok(levers.length >= 6);
    for (const l of levers) {
      assert.ok(l.savingUsd.low <= l.savingUsd.high && l.savingUsd.low >= 0, l.id);
      assert.ok(["low", "medium", "high"].includes(l.risk) && l.basis.length > 20, l.id);
    }
    assert.deepEqual(levers.map((l) => l.score), [...levers.map((l) => l.score)].sort((a, b) => b - a));
  });
  it("the Saka tier lever is sized from the real Saka spend", () => {
    const saka = sigs.filter((s) => s.tier === "saka").reduce((a, s) => a + s.costUsd, 0);
    const l = levers.find((x) => x.id === "saka-sonnet-5-5")!;
    assert.ok(Math.abs(l.affectedUsd - saka) < 1e-3);
    assert.ok(l.savingUsd.high < saka);
  });
