  it("turns the ChunkMirror regressions into golden-case, prompt-coach and routing candidates (never applied)", () => {
    const kinds = new Set(cands.map((c) => c.kind));
    for (const k of ["golden-case", "prompt-coach-gap", "routing-rule"]) assert.ok(kinds.has(k as never), k);
    for (const c of cands) { assert.equal(c.status, "candidate"); assert.ok(c.evidence.length >= 1 && c.confidence > 0 && c.confidence < 1); assert.ok((CANDIDATE_KINDS as readonly string[]).includes(c.kind)); }
    const g = cands.find((c) => c.kind === "golden-case" && c.evidence.includes(L.wand))!;
