    assert.deepEqual(mineCandidates(sigs).map((c) => c.id), cands.map((c) => c.id));
    assert.equal(candidateId("golden-case", "x"), candidateId("golden-case", "x"));
    const back = parseJsonl(toJsonl(cands) + "{broken\n" + JSON.stringify({ kind: "nope", id: "z", evidence: [] }) + "\n");
    assert.equal(back.length, cands.length);
  });
  it("a build set with no failures mines nothing", () => {
    const clean = sigs.filter((s) => s.kept && s.kind === "fresh");
    assert.deepEqual(mineCandidates(clean), []);
  });
  it("review markdown lists every kind and says nothing is applied", () => {
    const md = reviewMarkdown(cands, { generatedAt: "2026-10-12", builds: 27 });
    for (const k of CANDIDATE_KINDS) assert.ok(md.includes(`## ${k}`), k);
