  });
});

describe("engine release manifest", () => {
  const sha = (c: string) => c.repeat(64);
  const comps = (over: Partial<ManifestComponents> = {}): ManifestComponents => ({
    prompts: { base: "mb-2026-10-11.1", sections: { design: "mb-design-2026-10-10.1", config: "c1" } },
    sheets: [{ name: "paper-api-1.21.4.md", sha256: sha("b") }, { name: "paper-api-1.21.11.md", sha256: sha("a") }],
    rules: { version: "rules-2026-10-11.2", sha256: sha("c") }, scanner: { profile: "strict", sha256: sha("d") },
    image: { name: "nxeon-modbuilder", tag: "0.7" }, jdk: "21.0.12.1", ...over,
  });
  const baseline = { file: "services/modbuilder/eval/baseline.json", sha256: sha("e"), finalPassPct: 96.5, builds: 40, acceptedAt: "2026-10-12T00:00:00Z" };
  it("the id depends only on the components and ignores ordering", () => {
    const a = comps(), b = comps({ sheets: [...a.sheets].reverse(), prompts: { base: a.prompts.base, sections: { config: "c1", design: "mb-design-2026-10-10.1" } } });
    assert.equal(releaseId(a), releaseId(b));
    assert.notEqual(releaseId(a), releaseId(comps({ rules: { version: "rules-2026-10-12.1", sha256: sha("f") } })));
    assert.match(releaseId(a), /^er-[0-9a-f]{16}$/);
  });
  it("a draft is valid; live needs an eval baseline and a rollback pointer; a hand-edited id is caught", () => {
    const draft = createManifest({ components: comps(), now: new Date("2026-10-12T00:00:00Z") });
    assert.deepEqual(validateManifest(draft), []);
    const live = createManifest({ components: comps(), status: "live" });
    assert.deepEqual(validateManifest(live).sort(), ["a live release needs a rollback pointer", "a live release needs an eval baseline reference"]);
    assert.deepEqual(validateManifest(createManifest({ components: comps(), status: "live", evalBaseline: baseline, rollbackTo: "er-0000000000000000", rollbackHow: "TAG=modbuilder:0.6 scripts/cyrus/deploy-modbuilder.sh" })), []);
    assert.ok(validateManifest({ ...draft, id: "er-ffffffffffffffff" }).some((p) => /id does not match/.test(p)));
    assert.ok(validateManifest(createManifest({ components: comps({ rules: { version: "", sha256: "zz" } }) })).some((p) => /rules/.test(p)));
  });
  it("diff names the parts that changed, including sheets", () => {
    const a = createManifest({ components: comps() });
    const b = createManifest({ components: comps({ image: { name: "nxeon-modbuilder", tag: "0.8" }, sheets: [{ name: "paper-api-1.21.4.md", sha256: sha("9") }, { name: "paper-api-1.21.11.md", sha256: sha("a") }, { name: "paper-api-1.21.8.md", sha256: sha("8") }] }) });
    const d = diffManifests(a, b);
    assert.deepEqual(d.changed.sort(), ["image", "sheets"]);
    assert.deepEqual(d.sheets, { added: ["paper-api-1.21.8.md"], removed: [], changed: ["paper-api-1.21.4.md"] });
    assert.equal(diffManifests(a, a).same, true);
  });
  it("eval gate blocks a drop beyond the tolerance and a release with no eval", () => {
    assert.equal(evalGate(baseline, { ...baseline, finalPassPct: 96 }).ok, true);
    assert.equal(evalGate(baseline, { ...baseline, finalPassPct: 90 }).ok, false);
    assert.equal(evalGate(baseline, null).ok, false);
    assert.equal(evalGate(null, baseline).ok, true);
  });
  it("rollback target resolves inside the list of releases", () => {
    const prev = createManifest({ components: comps() });
    const next = createManifest({ components: comps({ image: { name: "nxeon-modbuilder", tag: "0.8" } }), rollbackTo: prev.id, rollbackHow: "redeploy the previous image tag" });
    assert.equal(rollbackTarget(next, [prev, next])?.id, prev.id);
    assert.equal(rollbackTarget(prev, [prev, next]), null);
  });
});

describe("flag", () => {
  it("CYRUS_LEARNING is off unless set", () => {
    assert.equal(learningEnabled({}), false);
    assert.equal(learningEnabled({ CYRUS_LEARNING: "0" }), false);
    assert.equal(learningEnabled({ CYRUS_LEARNING: "1" }), true);
    assert.equal(summarize(sigs).builds, 27);
  });
});
