    assert.ok(validateManifest(createManifest({ components: comps({ rules: { version: "", sha256: "zz" } }) })).some((p) => /rules/.test(p)));
  });
  it("diff names the parts that changed, including sheets", () => {
    const a = createManifest({ components: comps() });
    const b = createManifest({ components: comps({ image: { name: "nxeon-modbuilder", tag: "0.8" }, sheets: [{ name: "paper-api-1.21.4.md", sha256: sha("9") }, { name: "paper-api-1.21.11.md", sha256: sha("a") }, { name: "paper-api-1.21.8.md", sha256: sha("8") }] }) });
    const d = diffManifests(a, b);
    assert.deepEqual(d.changed.sort(), ["image", "sheets"]);
    assert.deepEqual(d.sheets, { added: ["paper-api-1.21.8.md"], removed: [], changed: ["paper-api-1.21.4.md"] });
    assert.equal(diffManifests(a, a).same, true);
  });
  it("eval gate blocks a drop beyond the tolerance and a release with no eval", () => {
    assert.equal(evalGate(baseline, { ...baseline, finalPassPct: 96 }).ok, true);
    assert.equal(evalGate(baseline, { ...baseline, finalPassPct: 90 }).ok, false);
    assert.equal(evalGate(baseline, null).ok, false);
    assert.equal(evalGate(null, baseline).ok, true);
  });
  it("rollback target resolves inside the list of releases", () => {
    const prev = createManifest({ components: comps() });
    const next = createManifest({ components: comps({ image: { name: "nxeon-modbuilder", tag: "0.8" } }), rollbackTo: prev.id, rollbackHow: "redeploy the previous image tag" });
    assert.equal(rollbackTarget(next, [prev, next])?.id, prev.id);
    assert.equal(rollbackTarget(prev, [prev, next]), null);
  });
});

describe("flag", () => {
  it("CYRUS_LEARNING is off unless set", () => {
    assert.equal(learningEnabled({}), false);
    assert.equal(learningEnabled({ CYRUS_LEARNING: "0" }), false);
    assert.equal(learningEnabled({ CYRUS_LEARNING: "1" }), true);
    assert.equal(summarize(sigs).builds, 27);
  });
});
