// Cyrus LEARNING LOOP step 2: the TOKEN-EFFICIENCY REPORT as markdown. Pure (the script scripts/cyrus/learning-report.ts does the
// reading). Carries no request text, no plugin names and no user ids: build ids, tiers, lanes, counts and dollars only.
import type { Summary, Group } from "./aggregate";
import type { Lever } from "./levers";
import type { BuildSignals } from "./types";

const usd = (n: number | null | undefined, d = 3) => (n == null ? "-" : "$" + n.toFixed(d));
const pct = (n: number) => (100 * n).toFixed(0) + "%";
const sum = (a: number[]) => a.reduce((x, y) => x + y, 0);
const median = (a: number[]) => { if (!a.length) return 0; const s = [...a].sort((x, y) => x - y); const m = s.length >> 1; return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2; };
const table = (head: string[], rows: (string | number)[][]) => [`| ${head.join(" | ")} |`, `|${head.map(() => "---").join("|")}|`, ...rows.map((r) => `| ${r.join(" | ")} |`)].join("\n");
const groupRows = (g: Group[]) => g.map((x) => [x.key, x.builds, x.succeeded, x.kept, x.reworked, usd(x.costUsd, 2), usd(x.avgCostUsd), x.avgTurns, usd(x.costPerSuccess), usd(x.costPerKept)]);
const GROUP_HEAD = ["key", "builds", "succeeded", "kept", "reworked", "spend", "avg $", "avg turns", "$ / success", "$ / kept success"];

export type ReportInput = { sigs: BuildSignals[]; summary: Summary; levers: Lever[]; generatedAt: string; sheetBytes?: number; source: string };

export function reportMarkdown(i: ReportInput): string {
  const { sigs, summary: S, levers } = i;
  const first = sigs.length ? new Date(Math.min(...sigs.map((s) => s.createdAtMs))).toISOString().slice(0, 10) : "-";
  const last = sigs.length ? new Date(Math.max(...sigs.map((s) => s.createdAtMs))).toISOString().slice(0, 10) : "-";
  const L: string[] = [];
  L.push(`# Cyrus token-efficiency baseline`, "", `Generated ${i.generatedAt}. Source: ${i.source}. Read-only; no prompt, sheet, route or flag was changed. ${S.builds} builds, ${first} to ${last}, total spend ${usd(S.totalCostUsd, 2)} (about ${S.totalTokensEst.toLocaleString("en-US")} Cyrus tokens at $0.002).`, "");
  L.push(`**Read this first.** The sample is small (${S.builds} builds, all from the owner) and the stored records have cost and turns per AI call but **no token counts**. Savings below are ESTIMATES with stated assumptions; the ranking is for deciding what to measure and try next, not a forecast.`, "");

  L.push(`## Headline`, "");
  L.push(`- ${S.succeeded}/${S.builds} builds succeeded; ${S.counts.kept} were "kept" successes (not followed by another change within 30 min and not a major regression). Cost per success ${usd(S.totalCostUsd / Math.max(1, S.succeeded), 3)}; cost per kept success ${usd(S.totalCostUsd / Math.max(1, S.counts.kept), 3)}.`);
  L.push(`- **Wasted spend**: ${usd(S.wasted.reworkUsd, 2)} (${pct(S.wasted.reworkUsd / Math.max(S.totalCostUsd, 1e-9))} of all spend) went on ${S.wasted.reworkBuilds} build(s) the owner followed with another change within 30 minutes; ${usd(S.wasted.majorRegressionUsd, 2)} on builds that dropped commands or most classes of the build they changed; ${usd(S.wasted.failedUsd, 4)} on failed builds.`);
  L.push(`- Signals: ${S.counts.guardRefusals} guard refusal(s), ${S.counts.interrupted} interruption(s), ${S.counts.unavailable} builder-unavailable, ${S.counts.testFlightFailures} Test Flight failure(s), ${S.counts.installFailures} install failure(s) recorded, ${S.counts.majorRegressions} major regression(s) vs the base build, ${S.counts.majorVsGood} vs the last good build.`, "");

  L.push(`## Spend by call kind`, "");
  const kinds = Object.entries(S.byKind).sort((a, b) => b[1].costUsd - a[1].costUsd);
  L.push(table(["kind", "calls", "turns", "spend", "share", "avg $/turn"], kinds.map(([k, c]) => [k, c.n, c.turns, usd(c.costUsd, 3), pct(c.share), c.turns ? usd(c.costUsd / c.turns, 4) : "-"])), "");
  L.push(`By model family and kind:`, "", table(["family/kind", "calls", "turns", "spend", "avg $/turn"], Object.entries(S.byFamilyKind).sort((a, b) => b[1].costUsd - a[1].costUsd).map(([k, c]) => [k, c.n, c.turns, usd(c.costUsd, 3), c.turns ? usd(c.costUsd / c.turns, 4) : "-"])), "");

  L.push(`## Spend by tier, model family, route and lane`, "");
  L.push(`**Tier** (the customer's choice, Katara/Saka/Yakko):`, "", table(GROUP_HEAD, groupRows(S.byTier)), "");
  L.push(`**Model family** actually called:`, "", table(GROUP_HEAD, groupRows(S.byFamily)), "");
  L.push(`**Route** (router class of the build; "none" = old builds before routing was stored):`, "", table(GROUP_HEAD, groupRows(S.byRoute)), "");
  L.push(`**Lane** (planned lanes; "plain" = no planner lane stored, i.e. a plain plugin or a build before the planner):`, "", table(GROUP_HEAD, groupRows(S.byLane)), "");
  L.push(`**Fresh vs change builds:**`, "", table(GROUP_HEAD, groupRows(S.freshVsChange)), "");

  L.push(`## Turns per build`, "");
  const ok = sigs.filter((s) => s.outcome === "success");
  const rows: (string | number)[][] = [];
  for (const kind of ["fresh", "change"] as const) for (const fam of ["haiku", "sonnet", "opus"] as const) {
    const l = ok.filter((s) => s.kind === kind && s.family === fam);
    if (l.length) rows.push([kind, fam, l.length, Math.min(...l.map((s) => s.turns)), median(l.map((s) => s.turns)), Math.max(...l.map((s) => s.turns)), usd(sum(l.map((s) => s.costUsd)) / l.length), usd(sum(l.map((s) => s.costUsd)) / Math.max(1, sum(l.map((s) => s.turns))), 4)]);
  }
  L.push(table(["kind", "family", "builds", "min turns", "median", "max", "avg $", "$ / turn"], rows), "");
  const planning = sum(sigs.map((s) => s.events.stageMs.planning ?? 0)), coding = sum(sigs.map((s) => s.events.stageMs.coding ?? 0)), compiling = sum(sigs.map((s) => s.events.stageMs.compiling ?? 0)), repairing = sum(sigs.map((s) => s.events.stageMs.repairing ?? 0));
  const tot = Math.max(1, planning + coding + compiling + repairing);
  L.push(`Wall time by stage from the stored events (builds with events only; planning includes the model's thinking before its first edit): planning ${pct(planning / tot)}, coding ${pct(coding / tot)}, compiling ${pct(compiling / tot)}, repairing ${pct(repairing / tot)}.`, "");

  L.push(`## The Haiku change builds`, "");
  const hc = sigs.filter((s) => s.kind === "change" && s.family === "haiku");
  if (hc.length) {
    L.push(table(["build", "turns", "$", "seconds", "outcome", "reworked", "vs base", "vs last good"], hc.map((s) => [s.id.slice(0, 12), s.turns, usd(s.costUsd), Math.round(s.durationMs / 1000), s.outcome, s.rework.reworked ? `yes (${s.rework.gapMin} min)` : "no", s.regression?.severity ?? "-", s.regressionVsGood?.severity ?? "-"])), "");
    const long = hc.filter((s) => s.turns >= 18).sort((a, b) => b.turns - a.turns)[0];
    if (long) L.push(`The longest, ${long.id.slice(0, 12)}, took ${long.turns} turns and cost ${usd(long.costUsd)} (${Math.round(long.durationMs / 1000)} s)${long.regressionVsGood?.severity === "major" ? " and removed the commands and classes of the last good build: cheap per turn, expensive in outcome" : ""}. Haiku change builds averaged ${(sum(hc.map((s) => s.turns)) / hc.length).toFixed(1)} turns and ${usd(sum(hc.map((s) => s.costUsd)) / hc.length)}.`, "");
  } else L.push("_none_", "");

  L.push(`## Wasted spend (re-requested within 30 minutes)`, "");
  const rw = sigs.filter((s) => s.rework.reworked);
  L.push(rw.length ? table(["build", "tier", "$", "followed by", "after (min)", "relation"], rw.map((s) => [s.id.slice(0, 12), s.tier ?? "-", usd(s.costUsd), s.rework.byId!.slice(0, 12), s.rework.gapMin!, s.rework.via!])) : "_none_", "");
  L.push(`A follow-up is not always a redo (a new feature request also counts), so treat this as an upper bound of waste; the mining job separates corrections by wording only when the operator passes the request text.`, "");

  L.push(`## Data gaps that limit learning`, "");
  L.push(S.usage ? `- Token usage persisted for ${S.usage.builds} build(s).` : `- **No token counts are stored** in ModBuild (the build service records them in \`aiCalls[].tokens\` / \`turnsDetail\`, but \`toResult\` in lib/modbuilder/store.ts drops them). With \`CYRUS_LEARNING\` on, the portal keeps them for new builds; until then the per-turn cache read / write / output split is the 0.5 analysis (output 61%, cache writes 33%, cache reads 6% on fresh Sonnet builds), not measured on these builds.`);
  L.push(`- No compiler or repair error TEXT is stored for successful builds (only counts), so failure-rule mining has little to cluster; the repair log lives on the build service.`);
  L.push(`- No install FAILURE is stored (\`lastInstall\` is written on success only), no in-game player report, no "owner kept using it" signal: the 30-minute rework window is the only quality signal available for successes.`);
  L.push(`- ${S.counts.testFlightFailures} Test Flight failure(s) are builds whose stored verdict is "failed" while every recorded check passed (early gate versions): treat as legacy.`, "");

  L.push(`## Levers, ranked`, "");
  L.push(`Score = mid saving divided by a risk weight (low 1, medium 1.6, high 3). Saving ranges are USD over this ${S.builds}-build sample (${usd(S.totalCostUsd, 2)}); percentages are of total spend.`, "");
  L.push(table(["#", "lever", "risk", "confidence", "affected $", "saving $ (low-high)", "% of spend (mid)", "score"], levers.map((l, k) => [k + 1, l.title, l.risk, l.confidence, usd(l.affectedUsd, 2), `${usd(l.savingUsd.low, 2)} - ${usd(l.savingUsd.high, 2)}`, pct(l.savingPct), l.score.toFixed(3)])), "");
  levers.slice(0, 5).forEach((l, k) => L.push(`### ${k + 1}. ${l.title}`, `- Change: ${l.change}`, `- Basis: ${l.basis}`, ""));
  const rest = levers.slice(5);
  if (rest.length) { L.push(`### Lower ranked`, ""); rest.forEach((l) => L.push(`- **${l.title}** (risk ${l.risk}, ${usd(l.savingUsd.low, 2)} - ${usd(l.savingUsd.high, 2)}): ${l.basis}`)); L.push(""); }

  L.push(`## Method and assumptions`, "");
  L.push(`- Signals: lib/cyrus/learning (rework = the next change of the same lineage, building on this build or its base, starting within 30 minutes of this build ending; regression = the build lost commands / sub-commands, or half its base's classes, or the lineage's last good build did; kept = succeeded, not reworked, no major regression).`);
  L.push(`- Class / command / config-key sets come from the stored result (\`files\`, \`commands\`, \`config\`). The stored \`config\` list can be shorter than the real config.yml, so a config-key loss alone is only "minor" unless both sides come from jars.`);
  L.push(`- Cost is the build service's API-equivalent USD (the owner is on a subscription today). 1 Cyrus token = $0.002 (D-03).`);
  L.push(`- Prices used for the sheet lever: input $/M haiku 1, sonnet 2, opus 5; cache read 0.1x; sheet ${i.sheetBytes ? Math.round(i.sheetBytes / 4) + " tokens (" + i.sheetBytes + " bytes / 4)" : "size not supplied"}.`);
  return L.join("\n") + "\n";
}
