// Shared by scripts/cyrus/learning-report.ts and learning-mine.ts: where the ModBuild rows come from. READ-ONLY by construction:
// psql runs with default_transaction_read_only=on and the only statement is one SELECT. The connection string comes from
// CYRUS_DATABASE_URL, else DATABASE_URL, and is never printed. Request text is NOT selected (its md5 stands in, which is enough to
// detect a word-for-word retry) unless the operator passes --include-prompts.
import { spawnSync } from "node:child_process";
import fs from "node:fs";
import type { BuildRow } from "../../lib/cyrus/learning/types";

const pgurl = (u: string) => u.replace(/([?&])(connection_limit|pool_timeout|schema|pgbouncer|socket_timeout|statement_cache_size)=[^&]*/g, "$1").replace(/&&+/g, "&").replace(/\?&/, "?").replace(/[?&]+$/, "");

export function selectSql(since: string, includePrompts: boolean): string {
  const text = includePrompts ? `prompt, "changeRequest"` : `md5(prompt) as prompt, case when "changeRequest" is null then null else md5("changeRequest") end as "changeRequest"`;
  return `select coalesce(json_agg(r order by r."createdAt"), '[]') from (
    select id, "userId", status, ${text}, "baseBuildId", "rootBuildId", "mcVersion", "pluginName", version, "errorCode", attempts, "costUsd", "durationMs", "createdAt", "finishedAt",
      jsonb_build_object('ai', result->'ai', 'repairs', result->'repairs', 'errorDetail', left(coalesce(result->>'errorDetail', ''), 60),
        'commands', (select coalesce(jsonb_agg(jsonb_build_object('usage', c->>'usage')), '[]'::jsonb) from jsonb_array_elements(case when jsonb_typeof(result->'commands') = 'array' then result->'commands' else '[]'::jsonb end) c),
        'config', (select coalesce(jsonb_agg(jsonb_build_object('key', c->>'key')), '[]'::jsonb) from jsonb_array_elements(case when jsonb_typeof(result->'config') = 'array' then result->'config' else '[]'::jsonb end) c),
        'files', (select coalesce(jsonb_agg(jsonb_build_object('path', f->>'path')), '[]'::jsonb) from jsonb_array_elements(case when jsonb_typeof(result->'files') = 'array' then result->'files' else '[]'::jsonb end) f where f->>'path' like '%.java'),
        'events', (select coalesce(jsonb_agg(jsonb_build_object('at', e->>'at', 'stage', e->>'stage', 'message', left(e->>'message', 80))), '[]'::jsonb) from jsonb_array_elements(case when jsonb_typeof(result->'events') = 'array' then result->'events' else '[]'::jsonb end) e)) as result,
      jsonb_build_object('model', cyrus->>'model', 'assets', jsonb_build_object('planned', cyrus->'assets'->'planned'),
        'testFlight', case when cyrus->'testFlight' is null then null else jsonb_build_object('state', cyrus->'testFlight'->>'state', 'verdict', cyrus->'testFlight'->>'verdict',
          'checks', (select coalesce(jsonb_agg(jsonb_build_object('id', c->>'id', 'status', c->>'status')), '[]'::jsonb) from jsonb_array_elements(case when jsonb_typeof(cyrus->'testFlight'->'checks') = 'array' then cyrus->'testFlight'->'checks' else '[]'::jsonb end) c),
          'stress', jsonb_build_object('verdict', cyrus->'testFlight'->'stress'->>'verdict')) end) as cyrus,
      case when "lastInstall" is null then null else jsonb_build_object('at', "lastInstall"->>'at', 'replaced', "lastInstall"->'replaced', 'error', "lastInstall"->'error') end as "lastInstall"
    from "ModBuild" where "createdAt" >= '${since}') r`;
}

/** Rows from --input <file> (JSON array of BuildRow-shaped objects) or from the database. Exits with a short message, never the URL. */
export function loadRows(argv: string[]): { rows: BuildRow[]; source: string } {
  const opt = (n: string) => { const i = argv.indexOf(`--${n}`); return i >= 0 && argv[i + 1] && !argv[i + 1].startsWith("--") ? argv[i + 1] : ""; };
  const input = opt("input");
  if (input) return { rows: JSON.parse(fs.readFileSync(input, "utf8")) as BuildRow[], source: `file ${input}` };
  const since = opt("since") || "2000-01-01";
  if (!/^\d{4}-\d{2}-\d{2}$/.test(since)) throw new Error("--since YYYY-MM-DD");
  const url = process.env.CYRUS_DATABASE_URL || process.env.DATABASE_URL;
  if (!url) throw new Error("set CYRUS_DATABASE_URL or DATABASE_URL (or pass --input rows.json)");
  const r = spawnSync("psql", [pgurl(url), "-XAtq", "-c", selectSql(since, argv.includes("--include-prompts"))], { env: { ...process.env, PGOPTIONS: "-c default_transaction_read_only=on" }, encoding: "utf8", maxBuffer: 256 * 1024 * 1024 });
  if (r.status !== 0) throw new Error("psql failed (" + String(r.stderr || "").split("\n")[0].replace(/postgres(ql)?:\/\/\S+/g, "<url>").slice(0, 160) + ")");
  return { rows: JSON.parse(r.stdout) as BuildRow[], source: `ModBuild table, read-only SELECT${since !== "2000-01-01" ? ` since ${since}` : ""}` };
}
EOF
