// Cyrus learning loop: TOKEN-EFFICIENCY REPORT (read-only). Reads ModBuild (one SELECT, read-only transaction) or a JSON file and
// writes a markdown report: spend by lane / model / route, turns per build, the Haiku change builds, wasted spend on re-requests,
// data gaps and the ranked token levers. Changes nothing: no prompt, sheet, route or flag.
//
//   npx tsx scripts/cyrus/learning-report.ts --out /root/agent-notes/cyrus-research/BJ-token-efficiency-baseline.md
//   npx tsx scripts/cyrus/learning-report.ts --input rows.json --json          (summary JSON to stdout)
// Options: --since YYYY-MM-DD, --out FILE (default stdout), --input FILE, --json, --sheet FILE (default services/modbuilder/sheets/1.21.11.md),
// --include-prompts (needed only for corrections wording in the mining job). Database: CYRUS_DATABASE_URL, else DATABASE_URL.
// Run on the primary only for this tiny read-only job: NODE_PATH=/opt/nxeon/node_modules /opt/nxeon/node_modules/.bin/tsx scripts/cyrus/learning-report.ts
import fs from "node:fs";
import path from "node:path";
import { deriveSignals } from "../../lib/cyrus/learning/signals";
import { summarize } from "../../lib/cyrus/learning/aggregate";
import { computeLevers } from "../../lib/cyrus/learning/levers";
import { reportMarkdown } from "../../lib/cyrus/learning/report";
import { loadRows } from "./learning-source";

const argv = process.argv.slice(2);
const opt = (n: string, d = "") => { const i = argv.indexOf(`--${n}`); return i >= 0 && argv[i + 1] && !argv[i + 1].startsWith("--") ? argv[i + 1] : d; };

const { rows, source } = loadRows(argv);
const sigs = deriveSignals(rows);
const summary = summarize(sigs);
const sheetFile = path.resolve(opt("sheet", path.join(__dirname, "../../services/modbuilder/sheets/1.21.11.md")));
const sheetBytes = fs.existsSync(sheetFile) ? fs.statSync(sheetFile).size : undefined;
const levers = computeLevers(sigs, { sheetBytes });
if (argv.includes("--json")) console.log(JSON.stringify({ summary, levers }, null, 1));
else {
  const md = reportMarkdown({ sigs, summary, levers, generatedAt: new Date().toISOString(), sheetBytes, source });
  if (opt("out")) { fs.writeFileSync(opt("out"), md); console.log(`wrote ${opt("out")} (${rows.length} builds)`); } else process.stdout.write(md);
}
EOF
