/** Rows from --input <file> (JSON array of BuildRow-shaped objects) or from the database. Exits with a short message, never the URL. */
export function loadRows(argv: string[]): { rows: BuildRow[]; source: string } {
  const opt = (n: string) => { const i = argv.indexOf(`--${n}`); return i >= 0 && argv[i + 1] && !argv[i + 1].startsWith("--") ? argv[i + 1] : ""; };
  const input = opt("input");
  if (input) return { rows: JSON.parse(fs.readFileSync(input, "utf8")) as BuildRow[], source: `file ${input}` };
  const since = opt("since") || "2000-01-01";
  if (!/^\d{4}-\d{2}-\d{2}$/.test(since)) throw new Error("--since YYYY-MM-DD");
  const url = process.env.CYRUS_DATABASE_URL || process.env.DATABASE_URL;
  if (!url) throw new Error("set CYRUS_DATABASE_URL or DATABASE_URL (or pass --input rows.json)");
  const r = spawnSync("psql", [pgurl(url), "-XAtq", "-c", selectSql(since, argv.includes("--include-prompts"))], { env: { ...process.env, PGOPTIONS: "-c default_transaction_read_only=on" }, encoding: "utf8", maxBuffer: 256 * 1024 * 1024 });
  if (r.status !== 0) throw new Error("psql failed (" + String(r.stderr || "").split("\n")[0].replace(/postgres(ql)?:\/\/\S+/g, "<url>").slice(0, 160) + ")");
  return { rows: JSON.parse(r.stdout) as BuildRow[], source: `ModBuild table, read-only SELECT${since !== "2000-01-01" ? ` since ${since}` : ""}` };
}
