// Cyrus LEARNING LOOP: where the mining job leaves its output and how the admin card reads it back. Server-only (node:fs).
// The job (scripts/cyrus/learning-mine.ts) writes summary.json, signals.jsonl (anonymized export records), candidates.jsonl and
// review.md into one directory: CYRUS_LEARNING_DIR, default ./.cyrus-learning (gitignored). Reading never throws: a missing or
// damaged file is an empty result, so the card shows "no job output yet".
import fs from "node:fs";
import path from "node:path";
import type { Summary } from "./aggregate";
import type { Lever } from "./levers";
import { parseJsonl, type Candidate } from "./mining";

export const LEARNING_DIR_ENV = "CYRUS_LEARNING_DIR";
export const learningDir = (env: Record<string, string | undefined> = process.env): string => path.resolve(env[LEARNING_DIR_ENV]?.trim() || path.join(process.cwd(), ".cyrus-learning"));

export type LearningOutput = { dir: string; generatedAt: string | null; source: string | null; summary: Summary | null; levers: Lever[]; candidates: Candidate[] };

export function readLearningOutput(dir = learningDir()): LearningOutput {
  const read = (f: string): string | null => { try { return fs.readFileSync(path.join(dir, f), "utf8"); } catch { return null; } };
  let meta: { generatedAt?: string; source?: string; summary?: Summary; levers?: Lever[] } = {};
  try { meta = JSON.parse(read("summary.json") ?? "{}"); } catch { meta = {}; }
  return {
    dir, generatedAt: meta.generatedAt ?? null, source: meta.source ?? null, summary: meta.summary ?? null, levers: Array.isArray(meta.levers) ? meta.levers : [],
    candidates: parseJsonl(read("candidates.jsonl") ?? "").slice(0, 200),
  };
}
EOF
cat > scripts/cyrus/learning-mine.ts <<'EOF'
// Cyrus learning loop: MINING JOB. Clusters failed / reworked / regressed builds into CANDIDATE items {kind: failure-rule | sheet-fact |
// golden-case | routing-rule | prompt-coach-gap, evidence build ids, proposed text, confidence} for a human to review. It NEVER writes to
// the rules, sheets, prompts or router: only to its own output directory (default ./.cyrus-learning, gitignored; CYRUS_LEARNING_DIR).
//
//   npx tsx scripts/cyrus/learning-mine.ts                       reads ModBuild read-only (CYRUS_DATABASE_URL / DATABASE_URL)
//   npx tsx scripts/cyrus/learning-mine.ts --input rows.json --out /tmp/learning
// Writes: candidates.jsonl, review.md, signals.jsonl (anonymized outcome records), summary.json (signals summary + ranked levers).
// Options: --since YYYY-MM-DD, --input FILE, --out DIR, --include-prompts (selects the request text so correction wording can be
// detected and quoted in review.md; staff-local only), --include-names (class / command names in proposed text), --min-evidence N.
import fs from "node:fs";
import path from "node:path";
import { deriveSignals } from "../../lib/cyrus/learning/signals";
import { summarize } from "../../lib/cyrus/learning/aggregate";
import { computeLevers } from "../../lib/cyrus/learning/levers";
import { mineCandidates, reviewMarkdown, toJsonl, type MiningText } from "../../lib/cyrus/learning/mining";
import { toExportRecord } from "../../lib/cyrus/learning/export";
import { learningDir } from "../../lib/cyrus/learning/files";
import { loadRows } from "./learning-source";

const argv = process.argv.slice(2);
const opt = (n: string, d = "") => { const i = argv.indexOf(`--${n}`); return i >= 0 && argv[i + 1] && !argv[i + 1].startsWith("--") ? argv[i + 1] : d; };

const { rows, source } = loadRows(argv);
const sigs = deriveSignals(rows);
const text: Record<string, MiningText> = {};
if (argv.includes("--include-prompts")) for (const r of rows) if (r.changeRequest) text[r.id] = { changeRequest: r.changeRequest };
const cands = mineCandidates(sigs, { text, includeNames: argv.includes("--include-names"), minEvidence: opt("min-evidence") ? parseInt(opt("min-evidence"), 10) : 1 });
const sheet = path.join(__dirname, "../../services/modbuilder/sheets/1.21.11.md");
const summary = summarize(sigs);
const levers = computeLevers(sigs, { sheetBytes: fs.existsSync(sheet) ? fs.statSync(sheet).size : undefined });
const generatedAt = new Date().toISOString();
const out = path.resolve(opt("out") || learningDir());
fs.mkdirSync(out, { recursive: true });
fs.writeFileSync(path.join(out, "candidates.jsonl"), toJsonl(cands));
fs.writeFileSync(path.join(out, "review.md"), reviewMarkdown(cands, { generatedAt, builds: sigs.length }));
fs.writeFileSync(path.join(out, "signals.jsonl"), sigs.map((s) => JSON.stringify(toExportRecord(s))).join("\n") + "\n");
fs.writeFileSync(path.join(out, "summary.json"), JSON.stringify({ generatedAt, source, summary, levers }, null, 1));
console.log(`${sigs.length} builds -> ${cands.length} candidate(s) in ${out} (candidates.jsonl, review.md, signals.jsonl, summary.json). Nothing was applied.`);
EOF
DBU=$(grep '^DATABASE_URL=' /opt/nxeon/.env | cut -d= -f2- | tr -d '"'); DATABASE_URL="$DBU" NODE_PATH=/opt/nxeon/node_modules /opt/nxeon/node_modules/.bin/tsx scripts/cyrus/learning-mine.ts --out /tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/learning-out 2>&1 | tail -3; head -c 1800 /tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/learning-out/review.md; git status --short | head

