cd /tank/dev-worktrees/cyrus-learning && cat > lib/cyrus/learning/usage.ts <<'EOF'
// Cyrus LEARNING LOOP: persist the per-call usage the build service already measures (services/modbuilder/usage.js) so the next
// report can say where the tokens went. The portal's toResult() (lib/modbuilder/store.ts) drops these today; with CYRUS_LEARNING on it
// keeps them, additively, on result.ai.calls[]. Pure; never throws. Numbers and tool NAMES only: no code, no prompt text.
export type CallUsageExtras = {
  tokens?: { uncached: number; cacheWrite: number; cacheRead: number; output: number; input: number };
  toolCalls?: Record<string, number>;
  apiMs?: number;
  explore?: boolean;
  /** Per API request: [uncached, cacheWrite, cacheRead, output, toolCount] (the tool-name column is dropped). Max 40 rows. */
  turnsDetail?: number[][];
};

const n = (v: unknown): number => (typeof v === "number" && Number.isFinite(v) && v >= 0 ? Math.round(v) : 0);
const rec = (v: unknown): Record<string, unknown> => (v && typeof v === "object" && !Array.isArray(v) ? (v as Record<string, unknown>) : {});

export function learningCallExtras(call: unknown): CallUsageExtras {
  const c = rec(call);
  const out: CallUsageExtras = {};
  const t = rec(c.tokens);
  if (Object.keys(t).length) out.tokens = { uncached: n(t.uncached ?? t.input), cacheWrite: n(t.cacheWrite), cacheRead: n(t.cacheRead), output: n(t.output), input: n(t.input) };
  const tc = rec(c.toolCalls);
  const names = Object.keys(tc).filter((k) => /^[A-Za-z_]{1,24}$/.test(k)).slice(0, 12);
  if (names.length) out.toolCalls = Object.fromEntries(names.map((k) => [k, n(tc[k])]));
  if (typeof c.apiMs === "number") out.apiMs = n(c.apiMs);
  if (typeof c.explore === "boolean") out.explore = c.explore;
  if (Array.isArray(c.turnsDetail)) out.turnsDetail = c.turnsDetail.slice(0, 40).map((r) => (Array.isArray(r) ? r.slice(0, 5).map(n) : [])).filter((r) => r.length === 5);
  return out;
}
EOF
