import type { Metadata } from "next";
import { realUser } from "@/lib/auth";
import { requireCyrusAdmin, cyrusAdminMetadata } from "@/lib/cyrus/admin/gate";
import { canCyrusAdmin } from "@/lib/cyrus/admin/perms";
import { platformStorage } from "@/lib/cyrus/admin/storage";
import { CATEGORY_LABEL, CATEGORY_ORDER } from "@/lib/cyrus/storage/accounting";
import { loadStorageConfig, storageAddonsEnabled, storageEnabled } from "@/lib/cyrus/storage/config";
import { fmtBytes, fmtCents } from "@/lib/cyrus/storage/pricing";
import { adminCyrusSetSetting } from "@/lib/actions-cyrus-admin";
import { AreaChart, MeterBar } from "@/components/ui/charts";
import { Badge, StatCard } from "@/components/ui/primitives";
import { Empty, Flash, Hidden, Section, TableWrap, UserLink, n, tdRow, thCls, usd, when } from "@/components/admin/cyrus/ui";

export const dynamic = "force-dynamic";
export async function generateMetadata(): Promise<Metadata> {
  return cyrusAdminMetadata("Storage");
}

const LIB_STATUS: Record<string, string> = { "pending-checks": "Staging (checks pending)", held: "Staging (held for review)", published: "Published", removed: "Removed (bytes purged, hash kept)" };
const TIER: Record<string, string> = { cc0: "CC0", "cc-by": "CC-BY", "proprietary-nxeon": "Proprietary (owner SFX + templates)", "user-contributed": "Customer contributions" };

/** Cyrus r51: total storage across every account, the content kinds, the asset library, backups and disks, cost, add-on revenue. */
export default async function CyrusStorageAdmin({ searchParams }: { searchParams: Promise<Record<string, string | string[] | undefined>> }) {
  await requireCyrusAdmin("storage");
  const me = (await realUser())!;
  const sp = await searchParams;
  const [p, cfg] = await Promise.all([platformStorage(25), loadStorageConfig()]);
  const total = p.accounts.usedBytes + p.accounts.pendingBytes;
  const maxCat = Math.max(1, ...CATEGORY_ORDER.map((c) => p.byCategory[c]));
  const canSet = canCyrusAdmin(me.role, "setting.set");
  const canExport = canCyrusAdmin(me.role, "storage.export");
  const libBytes = p.library.byStatus.filter((s) => s.status !== "removed").reduce((a, s) => a + s.bytes, 0);
  return (
    <div data-cyrus-storage>
      <Flash sp={sp} />
      <div className="mb-4 flex flex-wrap items-center gap-2">
        {storageEnabled() ? <Badge tone="green">metering + enforcement on</Badge> : <Badge tone="slate">CYRUS_STORAGE off: nothing measured or enforced</Badge>}
        {storageAddonsEnabled() ? <Badge tone="green">add-ons on sale</Badge> : <Badge tone="slate">add-ons off</Badge>}
        <Badge tone="amber">prices and quotas are placeholders</Badge>
        {canExport ? <span className="ml-auto flex gap-2"><a className="btn-secondary text-xs" href="/api/admin/cyrus/storage?kind=summary">CSV: summary</a><a className="btn-secondary text-xs" href="/api/admin/cyrus/storage?kind=accounts">CSV: accounts</a></span> : null}
      </div>

      {p.alerts.length ? (
        <div className="mb-5 space-y-2" role="status">
          {p.alerts.map((a, i) => <div key={i} className={`rounded-lg border px-3 py-2 text-sm ${a.level === "crit" ? "border-red-500/40 bg-red-500/10 text-red-200" : "border-amber-500/40 bg-amber-500/10 text-amber-100"}`}><b>{a.level === "crit" ? "Critical" : "Warning"}:</b> {a.text}</div>)}
        </div>
      ) : null}

      <div className="mb-6 grid grid-cols-2 gap-3 lg:grid-cols-4">
        <StatCard label="Customer storage (counted)" value={fmtBytes(total)} delta={`${n(p.accounts.count)} accounts measured`} />
        <StatCard label="Quota handed out" value={fmtBytes(p.accounts.quotaBytes)} delta={p.accounts.quotaBytes ? `${Math.round((total / p.accounts.quotaBytes) * 100)}% used` : "–"} />
        <StatCard label="Estimated disk cost / month" value={usd(p.cost.diskUsedUsd)} delta={`all used / and /tank (both hosts) at $${p.cost.usdPerGbMonth}/GB; customer data ${usd(p.cost.customerUsd)}`} />
        <StatCard label="Add-on run rate / month" value={fmtCents(p.addons.runRateCents)} delta={`${n(p.addons.active)} active · ${n(p.addons.gb)} GB · 30 d ${fmtCents(p.addons.revenue30dCents)}`} deltaGood={p.addons.pastDue === 0} />
      </div>

      <Section title="Disks and pools" sub={p.reportAt ? `live statfs + nightly report (${when(p.reportAt)})` : "live statfs on this host; node-2, ZFS pools and directory sizes need the nightly report (scripts/cyrus/storage-report.sh, not installed)"}>
        {p.disks.length ? (
          <TableWrap><table className="w-full text-sm"><thead><tr className={thCls}><th>Host</th><th>Mount / pool</th><th>Used</th><th className="hidden sm:table-cell">Size</th><th className="w-1/3">Usage</th><th className="hidden sm:table-cell">Source</th></tr></thead>
            <tbody>{p.disks.map((d) => (
              <tr key={`${d.host}${d.mount}${d.source}`} className={tdRow}><td className="whitespace-nowrap">{d.host}</td><td className="font-mono text-xs">{d.mount}</td><td className="whitespace-nowrap">{fmtBytes(d.used)}</td><td className="hidden whitespace-nowrap sm:table-cell">{fmtBytes(d.size)}</td>
                <td><div className="flex items-center gap-2"><MeterBar value={d.pct} max={100} color={d.pct >= cfg.poolCritPct ? "#ef4444" : d.pct >= cfg.poolWarnPct ? "#f59e0b" : "#6f47f5"} /><span className="w-12 text-right text-xs tabular-nums">{d.pct}%</span></div></td><td className="hidden text-xs text-slate-500 sm:table-cell">{d.source}</td></tr>
            ))}</tbody></table></TableWrap>
        ) : <Empty>No disk readings on this host.</Empty>}
        <p className="mt-2 text-xs text-slate-500">Alerts at {cfg.poolWarnPct}% (warning) and {cfg.poolCritPct}% (critical); the same thresholds run in scripts/cyrus/alert-check.sh (rules disk-*).</p>
      </Section>

      <div className="grid min-w-0 gap-4 lg:grid-cols-2">
        <Section title="What customers store" sub="from per-account measurements: shared bytes count once per account">
          <ul className="space-y-2">{CATEGORY_ORDER.map((c) => (
            <li key={c} className="text-sm"><div className="flex justify-between gap-2"><span>{CATEGORY_LABEL[c]}</span><span className="tabular-nums">{fmtBytes(p.byCategory[c])}</span></div><MeterBar value={p.byCategory[c]} max={maxCat} className="mt-1" /></li>
          ))}</ul>
          <p className="mt-3 text-xs text-slate-500">Raw tables (every account, no dedupe): {n(p.raw.jars)} stored jars {fmtBytes(p.raw.jarBytes)} · {n(p.raw.assets)} project assets {fmtBytes(p.raw.assetBytes)}.</p>
        </Section>
        <Section title="Account sizes" sub="distribution of measured accounts">
          <ul className="space-y-2">{p.accounts.distribution.map((b) => (
            <li key={b.label} className="text-sm"><div className="flex justify-between"><span>{b.label}</span><span className="tabular-nums">{n(b.count)}</span></div><MeterBar value={b.count} max={Math.max(1, ...p.accounts.distribution.map((x) => x.count))} className="mt-1" /></li>
          ))}</ul>
        </Section>
      </div>

import { notFound, redirect } from "next/navigation";
import { headers } from "next/headers";
import { CYRUS_ADMIN_HOST_HEADER } from "@/lib/cyrus/bridge/config";
import { realUser } from "@/lib/auth";
import { isPreviewUser } from "@/lib/preview-access";
import { visibleCyrusTabs } from "@/lib/cyrus/admin/perms";
import { cyrusModsPublicEnabled } from "@/lib/cyrus-mods/gate";
import { SubTabs } from "@/components/admin/SubTabs";
import { Badge } from "@/components/ui/primitives";

export const dynamic = "force-dynamic";

/**
 * /admin/cyrus: operating Cyrus (staff side). URL-only while Cyrus is in private preview (no
 * admin-nav entry, like /admin/mod-builder): the real account must be staff (admin layout) AND on
 * the "modbuilder" preview list, else 404. Each tab gates itself again with requireCyrusAdmin(tab),
 * and only the tabs the role may open are listed (lib/cyrus/admin/perms.ts).
 */
export default async function CyrusAdminLayout({ children }: { children: React.ReactNode }) {
  const user = await realUser();
  if (!user || !(await isPreviewUser(user, "modbuilder"))) notFound();
  const tabs = visibleCyrusTabs(user.role);
  // r51: on the secret Cyrus admin host there is no rest of /admin to fall back to
  if (!tabs.length) { if ((await headers()).get(CYRUS_ADMIN_HOST_HEADER) === "1") notFound(); redirect("/admin"); }
  const launched = await cyrusModsPublicEnabled();
  return (
    <div className="min-w-0" data-cyrus-admin>
      <div className="mb-3 flex flex-wrap items-end justify-between gap-3">
        <div className="min-w-0">
          <h1 className="page-title">Cyrus</h1>
          <p className="mt-1 text-sm text-slate-400">Operate the AI mod studio: builds, tokens, games and models, community, safety, and every admin action taken here.</p>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <Badge tone="brand">private preview</Badge>
          {launched ? <Badge tone="green">community: public</Badge> : <Badge tone="slate">community: preview only</Badge>}
        </div>
      </div>
      <SubTabs items={tabs.map((t) => ({ label: t.label, href: t.href }))} />
      <div className="mt-5 min-w-0">{children}</div>
    </div>
  );
}
// Page gate for /admin/cyrus/**. Server only.
//   1. role: requireArea(<the tab's area>) (lib/cyrus/admin/perms.ts) - redirects like every admin page;
//   2. private preview: the REAL signed-in account must be on the "modbuilder" allowlist, else a plain
//      404 (the section is indistinguishable from a route that does not exist), like /admin/mod-builder.
// The admin layout already refuses impersonation.
import { notFound } from "next/navigation";
import { getHost, type HostUser } from "../host";
import { CYRUS_ADMIN_TABS, type CyrusAdminTab } from "./perms";

export async function requireCyrusAdmin(tab: CyrusAdminTab): Promise<HostUser> {
  const area = CYRUS_ADMIN_TABS.find((t) => t.id === tab)!.area;
  const host = getHost();
  const user = await host.auth.requireArea(area);
  if (!(await host.access.isPreviewUser(await host.auth.realUser(), "modbuilder"))) notFound();
  return user;
}

export async function cyrusAdminMetadata(title: string) {
  const host = getHost();
  const ok = await host.access.isPreviewUser(await host.auth.realUser().catch(() => null), "modbuilder");
  return { title: ok ? `Cyrus · ${title}` : "Page not found", robots: { index: false, follow: false } };
}

/**
 * Route-handler guard for /api/admin/cyrus/** (r40). Same rule as the pages and the server actions, but returns null
 * instead of redirecting, so the route answers a plain 404: the real account, not impersonating, on the "modbuilder"
 * preview list, with the action's role area. Fails closed on any error.
 */
export async function cyrusAdminApiUser(action: import("./perms").CyrusAdminAction): Promise<HostUser | null> {
  try {
    const { CYRUS_ADMIN_ACTIONS } = await import("./perms");
    const host = getHost();
    const [real, cur] = await Promise.all([host.auth.realUser(), host.auth.currentUser()]);
    if (!real || !cur || real.id !== cur.id) return null;
    if (!host.access.canAccess(real.role, CYRUS_ADMIN_ACTIONS[action])) return null;
    if (!(await host.access.isPreviewUser(real, "modbuilder"))) return null;
    return real;
  } catch {
    return null;
  }
}
