  const payments = planPays.map((p) => { const m = meta(p.meta); return m.livemode === false ? null : { userId: p.userId, tier: typeof m.tier === "string" ? m.tier : null, cents: typeof m.amountPaid === "number" ? m.amou
  const margins = planMargins({ tiers: PLAN_TIERS, plans, payments, spend: new Map(users.map((u) => [u.userId, u.d30])), listCents: cfg.plan.cents });
