import type { Metadata } from "next";
import Link from "next/link";
import { requireCyrusAdmin, cyrusAdminMetadata } from "@/lib/cyrus/admin/gate";
import { learningEnabled } from "@/lib/cyrus/learning/flag";
import { readLearningOutput } from "@/lib/cyrus/learning/files";
import { Badge, StatCard } from "@/components/ui/primitives";
import { Empty, Section, TableWrap, n, pct, tdRow, thCls, usd } from "@/components/admin/cyrus/ui";

export const dynamic = "force-dynamic";
export async function generateMetadata(): Promise<Metadata> {
  return cyrusAdminMetadata("Learning");
}

const KIND_TONE = { "failure-rule": "red", "sheet-fact": "slate", "golden-case": "green", "routing-rule": "amber", "prompt-coach-gap": "brand" } as const;

/**
 * Cyrus learning loop (2026-10-12): READ-ONLY view of what scripts/cyrus/learning-mine.ts left behind: the outcome-signal summary,
 * the ranked token levers and the candidate list. Nothing here applies anything; candidates are reviewed by a human and shipped as
 * a normal branch (docs/cyrus/15-learning-loop.md). Off unless CYRUS_LEARNING is set.
 */
export default async function CyrusLearning() {
  await requireCyrusAdmin("learning");
  if (!learningEnabled()) {
    return (
      <Section title="Learning loop" sub="Mines real build outcomes into reviewed rules, sheet facts, golden cases and routing changes. Cyrus cannot fine-tune a model; this is how it improves.">
        <Empty>Off. Set <span className="font-mono">CYRUS_LEARNING=1</span> to show the signals and candidates here (and to keep token usage on new builds). The job itself is <span className="font-mono">scripts/cyrus/learning-mine.ts</span> and runs without the flag.</Empty>
      </Section>
    );
  }
  const out = readLearningOutput();
  const s = out.summary;
  return (
    <div data-cyrus-learning>
      <div className="mb-4 flex flex-wrap items-center gap-2">
        <Badge tone="green">CYRUS_LEARNING on</Badge>
        <Badge tone="slate">read-only: nothing is applied from here</Badge>
        {out.generatedAt ? <span className="text-xs text-slate-500">job output {out.generatedAt.replace("T", " ").slice(0, 16)} UTC · {out.source}</span> : null}
      </div>
      {!s ? (
        <Empty>No job output yet in <span className="font-mono">{out.dir}</span>. Run <span className="font-mono">npx tsx scripts/cyrus/learning-mine.ts</span> (read-only on ModBuild) and reload.</Empty>
      ) : (
        <>
          <div className="mb-6 grid grid-cols-2 gap-3 lg:grid-cols-5">
            <StatCard label="Builds analysed" value={n(s.builds)} delta={`${n(s.succeeded)} succeeded`} />
            <StatCard label="Kept successes" value={n(s.counts.kept)} delta="not re-requested in 30 min, no major regression" deltaGood={s.counts.kept >= s.succeeded * 0.8} />
            <StatCard label="Wasted on re-requests" value={usd(s.wasted.reworkUsd)} delta={`${n(s.wasted.reworkBuilds)} builds, ${pct(s.wasted.reworkUsd / Math.max(s.totalCostUsd, 1e-9))} of spend`} deltaGood={s.wasted.reworkBuilds === 0} />
            <StatCard label="Major regressions" value={n(s.counts.majorRegressions + s.counts.majorVsGood)} delta="lost commands or most classes" deltaGood={s.counts.majorRegressions + s.counts.majorVsGood === 0} />
            <StatCard label="Guard refusals" value={n(s.counts.guardRefusals)} delta={`${n(s.counts.interrupted)} interrupted · ${n(s.counts.unavailable)} unavailable`} />
          </div>

          <Section title="Outcome by tier" sub="the customer's model choice; cost per kept success is the number to bring down">
            <TableWrap><table className="w-full text-sm"><thead><tr className={thCls}><th>Tier</th><th>Builds</th><th>Succeeded</th><th>Kept</th><th>Re-requested</th><th>Spend</th><th>Avg turns</th><th>$ / success</th><th>$ / kept</th></tr></thead>
              <tbody>{s.byTier.map((g) => <tr key={g.key} className={tdRow}><td>{g.key}</td><td>{n(g.builds)}</td><td>{n(g.succeeded)}</td><td>{n(g.kept)}</td><td>{n(g.reworked)}</td><td>{usd(g.costUsd)}</td><td>{g.avgTurns}</td><td>{usd(g.costPerSuccess, 3)}</td><td>{usd(g.costPerKept, 3)}</td></tr>)}</tbody></table></TableWrap>
          </Section>

          <Section title="Token levers, ranked" sub="estimates with stated assumptions (no token counts are stored for old builds); score = mid saving / risk weight">
            {out.levers.length ? (
              <TableWrap><table className="w-full text-sm"><thead><tr className={thCls}><th>Lever</th><th>Risk</th><th>Confidence</th><th>Saving (sample)</th><th>% of spend</th></tr></thead>
                <tbody>{out.levers.map((l) => <tr key={l.id} className={tdRow}><td className="min-w-[16rem]"><b>{l.title}</b><div className="text-xs text-slate-500">{l.change}</div></td><td><Badge tone={l.risk === "low" ? "green" : l.risk === "medium" ? "amber" : "red"}>{l.risk}</Badge></td><td>{l.confidence}</td><td className="whitespace-nowrap">{usd(l.savingUsd.low)} – {usd(l.savingUsd.high)}</td><td>{pct(l.savingPct)}</td></tr>)}</tbody></table></TableWrap>
            ) : <Empty>No levers in the job output.</Empty>}
          </Section>

          <Section title={`Candidates (${out.candidates.length})`} sub="proposed rules, sheet facts, golden cases, routing changes and coach gaps. Accept = a person writes it in a normal branch with tests; none of these is live.">
            {out.candidates.length ? (
              <ul className="space-y-2">{out.candidates.map((c) => (
                <li key={c.id} className="rounded-lg border border-white/[0.08] px-3 py-2 text-sm">
                  <div className="flex flex-wrap items-center gap-2"><Badge tone={KIND_TONE[c.kind]}>{c.kind}</Badge><b className="min-w-0 flex-1">{c.title}</b><span className="text-xs text-slate-500">confidence {c.confidence}</span></div>
                  <p className="mt-1 text-xs text-slate-400">{c.rationale}</p>
                  <details className="mt-1"><summary className="cursor-pointer text-xs text-slate-500">proposed text and evidence</summary>
                    <p className="mt-1 whitespace-pre-wrap break-words text-xs">{c.proposedText}</p>
                    <p className="mt-1 text-xs">{c.evidence.map((id) => <Link key={id} className="mr-2 font-mono underline" href={`/admin/cyrus/builds/${id}`}>{id.slice(0, 12)}</Link>)}</p>
                  </details>
                </li>
              ))}</ul>
            ) : <Empty>No candidates: nothing failed, regressed or was re-requested in the analysed builds.</Empty>}
          </Section>
        </>
      )}
    </div>
  );
}
