          <Section title={`Candidates (${out.candidates.length})`} sub="proposed rules, sheet facts, golden cases, routing changes and coach gaps. Accept = a person writes it in a normal branch with tests; none of these is live.">
            {out.candidates.length ? (
              <ul className="space-y-2">{out.candidates.map((c) => (
