// Learning loop: the two scripts run end to end on the production fixture (--input, no database), the output reader, the usage
// capture helper and the guardrails (never touches rules / sheets / prompts; read-only SQL). No AI, no network.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { prodRows } from "./fixtures/cyrus-learning/rows";
import { learningCallExtras } from "../lib/cyrus/learning/usage";
import { readLearningOutput } from "../lib/cyrus/learning/files";
import { selectSql } from "../scripts/cyrus/learning-source";

const ROOT = path.resolve(__dirname, "..");
const run = (script: string, args: string[]) => spawnSync(process.execPath, ["--import", "tsx", path.join(ROOT, "scripts/cyrus", script), ...args], { cwd: ROOT, encoding: "utf8", env: { ...process.env, DATABASE_URL: "", CYRUS_DATABASE_URL: "" } });

describe("learning scripts", () => {
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), "cyrus-learning-"));
  const input = path.join(tmp, "rows.json");
  fs.writeFileSync(input, JSON.stringify(prodRows()));

  it("learning-mine writes candidates, review page, anonymized signals and a summary, and only there", () => {
    const out = path.join(tmp, "out");
    const r = run("learning-mine.ts", ["--input", input, "--out", out]);
    assert.equal(r.status, 0, r.stderr);
    assert.deepEqual(fs.readdirSync(out).sort(), ["candidates.jsonl", "review.md", "signals.jsonl", "summary.json"]);
    const o = readLearningOutput(out);
    assert.equal(o.summary?.builds, 27);
    assert.ok(o.candidates.length >= 4 && o.candidates.every((c) => c.status === "candidate"));
    assert.ok(o.levers.length >= 6);
    const signals = fs.readFileSync(path.join(out, "signals.jsonl"), "utf8").trim().split("\n");
    assert.equal(signals.length, 27);
    assert.ok(!/chunkmirror|owner/i.test(signals.join("\n")), "signals.jsonl is anonymized");
    assert.match(fs.readFileSync(path.join(out, "review.md"), "utf8"), /nothing here is applied/i);
  });
  it("learning-report writes a markdown report with the key sections", () => {
    const file = path.join(tmp, "report.md");
    const r = run("learning-report.ts", ["--input", input, "--out", file]);
    assert.equal(r.status, 0, r.stderr);
    const md = fs.readFileSync(file, "utf8");
    for (const h of ["## Spend by call kind", "## Spend by tier, model family, route and lane", "## Turns per build", "## The Haiku change builds", "## Wasted spend", "## Data gaps", "## Levers, ranked"]) assert.ok(md.includes(h), h);
    assert.match(md, /27 builds/);
    assert.ok(!/ChunkMirror|Banshee/.test(md), "no plugin names in the report");
  });
  it("without a database or --input the script stops with a short message and no URL", () => {
    const r = run("learning-report.ts", []);
    assert.notEqual(r.status, 0);
    assert.match(r.stderr, /CYRUS_DATABASE_URL or DATABASE_URL/);
  });
  it("the SQL is a single SELECT; request text is hashed unless asked for", () => {
    const sql = selectSql("2026-10-01", false);
    assert.match(sql, /^\s*select /);
    assert.ok(!/\b(insert|update|delete|drop|alter|create|truncate|grant)\b/i.test(sql));
    assert.match(sql, /md5\(prompt\)/);
    assert.match(selectSql("2026-10-01", true), /prompt, "changeRequest"/);
  });
  it("a missing output directory reads as empty (the admin card says no output yet)", () => {
    const o = readLearningOutput(path.join(tmp, "nope"));
    assert.equal(o.summary, null);
    assert.deepEqual(o.candidates, []);
  });
});

describe("usage capture", () => {
  it("keeps numbers and tool names only, caps the turn rows, never throws", () => {
    const x = learningCallExtras({ kind: "change", tokens: { uncached: 5, cacheWrite: 100.4, cacheRead: 1000, output: 50, input: 1105 }, toolCalls: { Read: 3, "bad name!": 9 }, apiMs: 1234, explore: false,
      turnsDetail: Array.from({ length: 60 }, () => [1, 2, 3, 4, 5, "Write,Write"]) });
    assert.deepEqual(x.tokens, { uncached: 5, cacheWrite: 100, cacheRead: 1000, output: 50, input: 1105 });
    assert.deepEqual(x.toolCalls, { Read: 3 });
    assert.equal(x.turnsDetail?.length, 40);
    assert.deepEqual(x.turnsDetail?.[0], [1, 2, 3, 4, 5]);
    assert.deepEqual(learningCallExtras(null), {});
    assert.deepEqual(learningCallExtras({ tokens: "x", toolCalls: 5, turnsDetail: "y" }), {});
  });
});
EOF
