// Learning loop step 4: the admin Learning page is read-only, gated like every Cyrus admin tab, and off without CYRUS_LEARNING.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { CYRUS_ADMIN_TABS, canSeeCyrusTab, visibleCyrusTabs } from "../lib/cyrus/admin/perms";

const page = fs.readFileSync(path.join(__dirname, "../app/admin/cyrus/learning/page.tsx"), "utf8");

describe("admin Learning tab", () => {
  it("is an ADMIN (fleet) tab like Builds and Storage, after Storage", () => {
    const t = CYRUS_ADMIN_TABS.find((x) => x.id === "learning")!;
    assert.deepEqual([t.area, t.href], ["fleet", "/admin/cyrus/learning"]);
    assert.equal(canSeeCyrusTab("ADMIN", "learning"), true);
    assert.equal(canSeeCyrusTab("SUPPORT", "learning"), false);
    assert.equal(canSeeCyrusTab("BILLING", "learning"), false);
    const ids = visibleCyrusTabs("ADMIN").map((x) => x.id);
    assert.equal(ids.indexOf("learning"), ids.indexOf("storage") + 1);
  });
  it("the page gates itself, checks the flag before reading anything, and has no form, action or write", () => {
    assert.match(page, /requireCyrusAdmin\("learning"\)/);
    assert.ok(page.indexOf("learningEnabled()") < page.indexOf("readLearningOutput()"), "flag is checked before the job output is read");
    assert.ok(!/<form|"use server"|action=|cyrusDb|\bdb\./.test(page), "read-only: no form, server action or database write");
  });
});
EOF
